function DashboardPage(props) {
  return <DashboardPagePolished {...props} />;
}

function DashboardPagePolished({
  stats,
  dashboardMetrics,
  leads,
  jobs,
  queueItems,
  activity,
  leadFilter,
  setLeadFilter,
  leadSearch,
  setLeadSearch,
  selectedLeadId,
  onSelectLead,
  selectedJobId,
  onSelectJob,
  selectedLead,
  onLeadFieldChange,
  onScoreLead,
  onCheckMissingInfo,
  onGenerateLeadAssistant,
  leadAssistantState,
  onCreateJobFromLead,
  onCreateEstimateFromLead,
  onConvertLeadToCustomer,
  onArchiveLead,
  onRestoreLead,
  onDeleteLead,
  leadSaveState,
  users,
  customers,
  contactHistory = [],
  permissions,
  onSelectCustomer,
  relatedLeadRecords,
  onCreateContactHistory,
  onUpdateContactHistory,
  onArchiveContactHistory,
  onRestoreContactHistory,
  taskDraft,
  setTaskDraft,
  onAddTask,
  onToggleTask,
  onArchiveTask,
  onRestoreTask,
  onDeleteTask,
  setActive,
  dashboardShortcuts,
  dashboardFocusTarget,
  onRunDashboardShortcut,
  busy,
}) {
  const queueRef = useRef(null);
  const jobsRef = useRef(null);
  const leadPipelineRef = useRef(null);
  const [showOfficeTools, setShowOfficeTools] = useState(false);
  const [showBackTop, setShowBackTop] = useState(false);

  useEffect(() => {
    const targets = {
      queue: queueRef.current,
      jobs: jobsRef.current,
      leads: leadPipelineRef.current,
    };
    const nextTarget = targets[dashboardFocusTarget];
    if (!nextTarget) return;
    nextTarget.scrollIntoView({ behavior: "smooth", block: "start" });
    nextTarget.focus({ preventScroll: true });
  }, [dashboardFocusTarget]);

  useEffect(() => {
    function handleScroll() {
      const shouldShow = window.scrollY > 520;
      setShowBackTop((current) => (current === shouldShow ? current : shouldShow));
    }

    handleScroll();
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const tabs = (Array.isArray(dashboardShortcuts) ? dashboardShortcuts : []).map((shortcut) => (
    <button
      key={shortcut.id}
      type="button"
      onClick={() => onRunDashboardShortcut?.(shortcut.id)}
      aria-label={shortcut.ariaLabel || shortcut.label}
      className={`shrink-0 rounded-2xl border px-3 py-2 text-left text-xs font-black transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2 ${
        shortcut.id === "today"
          ? "border-blue-700 bg-blue-700 text-white hover:bg-blue-800"
          : "border-blue-100 bg-blue-50 text-blue-700 hover:border-blue-200 hover:bg-white"
      }`}
    >
      <span className="block whitespace-nowrap">{shortcut.label}</span>
    </button>
  ));

  const visibleLeads = useMemo(() => {
    const searchValue = leadSearch.toLowerCase();
    return normalizeObjectArray(leads).filter((lead) => {
      const matchesArchive = leadFilter === "Archived" ? Boolean(lead.archivedAt) : !lead.archivedAt;
      const matchesFilter = leadFilter === "All" || leadFilter === "Archived" ? true : lead.status === leadFilter;
      const matchesSearch = [lead.customer, lead.project, lead.city, lead.owner].some((value) => String(value || "").toLowerCase().includes(searchValue));
      return matchesArchive && matchesFilter && matchesSearch;
    });
  }, [leadFilter, leadSearch, leads]);
  const liveLeadCount = dashboardMetrics?.liveLeadCount ?? 0;
  const liveJobsPreview = Array.isArray(dashboardMetrics?.liveJobsPreview) ? dashboardMetrics.liveJobsPreview : [];
  const canViewLeads = Boolean(permissions?.leads?.canView);
  const normalizedQueueItems = useMemo(() => normalizeObjectArray(queueItems), [queueItems]);
  const activeQueueItems = useMemo(() => normalizedQueueItems.filter((item) => !item.archivedAt && !item.done), [normalizedQueueItems]);
  const fieldDashboardActions = useMemo(() => (
    [
      { title: "My jobs", description: "Open assigned jobs and field-visible planning work.", icon: "briefcase", moduleId: "jobs", badge: "Open", tone: "blue" },
      { title: "Daily reports", description: "Capture field progress and crew updates for visible jobs.", icon: "document", moduleId: permissions?.reports?.canView ? "reports" : null, badge: permissions?.reports?.canView ? "Open" : "Off", tone: permissions?.reports?.canView ? "blue" : "slate" },
      { title: "Upload photo", description: "Send jobsite photos and documentation to the office.", icon: "upload", moduleId: permissions?.uploads?.canView ? "uploads" : null, badge: permissions?.uploads?.canView ? "Open" : "Off", tone: permissions?.uploads?.canView ? "blue" : "slate" },
      { title: "Time tracking", description: "Clock in, clock out, and review your field time.", icon: "clock", moduleId: permissions?.time?.canView ? "time" : null, badge: permissions?.time?.canView ? "Open" : "Off", tone: permissions?.time?.canView ? "blue" : "slate" },
      { title: "Safety & PPE", description: "Review site safety reminders and submit field concerns.", icon: "hardhat", moduleId: "ppe", badge: "Open", tone: "green" },
      { title: "Tool checklist", description: "Confirm assigned tools when the module is enabled.", icon: "clipboard", moduleId: permissions?.toolChecklist?.canUse ? "toolChecklist" : null, badge: permissions?.toolChecklist?.canUse ? "Open" : "Off", tone: permissions?.toolChecklist?.canUse ? "green" : "slate" },
    ]
  ), [permissions?.reports?.canView, permissions?.time?.canView, permissions?.toolChecklist?.canUse, permissions?.uploads?.canView]);
  const pipelineValue = Number(stats.pipelineValue || 0);
  const visibleLeadRowCap = 2;
  const visibleJobRowCap = 2;
  const visibleJobRows = liveJobsPreview.slice(0, visibleJobRowCap);
  const openQueueCount = activeQueueItems.length;
  const dueQueueCount = activeQueueItems.filter((item) => item.status === "Due today").length;
  const readyQueueCount = activeQueueItems.filter((item) => item.status === "Ready").length;
  const blockedQueueCount = activeQueueItems.filter((item) => item.status === "Blocked").length;
  const startupNeedsAttention = Number(stats.startupReviewJobs || 0) + Number(stats.startupMissingCrewStart || 0);
  const dashboardKpis = [
    { label: "New Leads", value: Number(stats.newLeads || 0), helper: `${stats.highPriorityLeads || 0} high priority`, icon: "inbox", tone: "blue", actionLabel: "View new", onAction: () => { setLeadFilter("New"); focusDashboardRef(leadPipelineRef); } },
    { label: "Open Pipeline", value: pipelineValue, displayValue: compactCurrency(pipelineValue), helper: `${currency(pipelineValue)} open / ${liveLeadCount} live`, icon: "quote", tone: "orange", actionLabel: "Review pipeline", onAction: () => { setLeadFilter("All"); focusDashboardRef(leadPipelineRef); } },
    { label: "Active Jobs", value: Number(stats.activeJobs || 0), helper: `${stats.scheduledJobs || 0} scheduled next`, icon: "briefcase", tone: "green", actionLabel: "View jobs", onAction: () => focusDashboardRef(jobsRef) },
    { label: "Reports Due", value: Number(stats.reportsDue || 0), helper: `${openQueueCount} queue item${openQueueCount === 1 ? "" : "s"} open`, icon: "document", tone: Number(stats.reportsDue || 0) ? "amber" : "slate", actionLabel: permissions?.reports?.canView ? "Open reports" : "Review queue", onAction: () => (permissions?.reports?.canView ? setActive("reports") : openDashboardTools(queueRef)) },
    { label: "Startup Watch", value: startupNeedsAttention, helper: `${stats.startupReadyJobs || 0} ready for field`, icon: "alert", tone: startupNeedsAttention ? "amber" : "green", actionLabel: "Review jobs", onAction: () => focusDashboardRef(jobsRef) },
  ];
  const blockedWorkCount = Math.max(blockedQueueCount, Number(stats.queueBlocked || 0));
  const attentionCount = Number(stats.reportsDue || 0) + startupNeedsAttention + dueQueueCount + blockedWorkCount;
  const dashboardPriorityCards = [
    {
      title: "Needs attention today",
      value: attentionCount,
      description: `${Number(stats.reportsDue || 0)} reports due / ${dueQueueCount} queue due / ${startupNeedsAttention} startup checks`,
      badge: "Attention",
      icon: "alert",
      tone: attentionCount ? "amber" : "green",
      primaryLabel: permissions?.jobs?.canManageAll ? "Open Command Center" : "Review Queue",
      onPrimary: () => (permissions?.jobs?.canManageAll ? setActive("commandCenter") : openDashboardTools(queueRef)),
      secondaryLabel: "Queue tools",
      onSecondary: () => openDashboardTools(queueRef),
    },
    {
      title: "Ready to move",
      value: Number(stats.startupReadyJobs || 0) + readyQueueCount,
      description: `${stats.startupReadyJobs || 0} jobs ready / ${readyQueueCount} queue items ready`,
      badge: "Ready",
      icon: "check",
      tone: "green",
      primaryLabel: "Review jobs",
      onPrimary: () => focusDashboardRef(jobsRef),
      secondaryLabel: "Open jobs",
      onSecondary: () => setActive("jobs"),
    },
    {
      title: "Pipeline next",
      value: Number(stats.newLeads || 0) + Number(stats.highPriorityLeads || 0),
      description: `${stats.newLeads || 0} new leads / ${stats.highPriorityLeads || 0} high priority`,
      badge: "Leads",
      icon: "users",
      tone: "blue",
      primaryLabel: "Review leads",
      onPrimary: () => { setLeadFilter("New"); focusDashboardRef(leadPipelineRef); },
      secondaryLabel: "Open leads",
      onSecondary: () => setActive("leads"),
    },
    {
      title: "Blocked work",
      value: blockedWorkCount,
      description: blockedWorkCount ? "Blocked queue items need owner decision before the day moves." : "No blocked queue items right now.",
      badge: "Blocked",
      icon: "clipboard",
      tone: blockedWorkCount ? "red" : "slate",
      primaryLabel: "Review blockers",
      onPrimary: () => openDashboardTools(queueRef),
      secondaryLabel: permissions?.jobs?.canManageAll ? "Command Center" : "",
      onSecondary: () => setActive("commandCenter"),
    },
  ];
  const fieldKpis = [
    { label: "Visible Jobs", value: liveJobsPreview.length, helper: "Assigned and field-visible work", icon: "briefcase", tone: "blue", actionLabel: "Open jobs", onAction: () => setActive("jobs") },
    { label: "Daily Reports", value: permissions?.reports?.canView ? 1 : 0, helper: permissions?.reports?.canView ? "Available today" : "Not enabled", icon: "document", tone: permissions?.reports?.canView ? "green" : "slate", actionLabel: permissions?.reports?.canView ? "Open reports" : "Unavailable", onAction: () => permissions?.reports?.canView && setActive("reports") },
    { label: "Uploads", value: permissions?.uploads?.canView ? 1 : 0, helper: permissions?.uploads?.canView ? "Photo tools on" : "Not enabled", icon: "upload", tone: permissions?.uploads?.canView ? "green" : "slate", actionLabel: permissions?.uploads?.canView ? "Open uploads" : "Unavailable", onAction: () => permissions?.uploads?.canView && setActive("uploads") },
    { label: "Time Tools", value: permissions?.time?.canView ? 1 : 0, helper: permissions?.time?.canView ? "Clock tools on" : "Not enabled", icon: "clock", tone: permissions?.time?.canView ? "green" : "slate", actionLabel: permissions?.time?.canView ? "Open time" : "Unavailable", onAction: () => permissions?.time?.canView && setActive("time") },
  ];

  function focusDashboardRef(ref) {
    ref.current?.scrollIntoView?.({ behavior: "smooth", block: "start" });
    ref.current?.focus?.({ preventScroll: true });
  }

  function openDashboardTools(ref = queueRef) {
    setShowOfficeTools(true);
    window.setTimeout(() => focusDashboardRef(ref), 0);
  }

  function scrollDashboardTop() {
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  if (!canViewLeads) {
    return (
      <div className="co-office-page co-dashboard-page co-dashboard-field-page">
        <PageHeader
          eyebrow="Field Workspace"
          title="Daily workspace"
          description="Open assigned jobs, reports, uploads, safety tools, and time tracking without exposing office-only data."
          actions={
            <div className="flex flex-wrap gap-2">
              <Button type="button" variant="secondary" onClick={() => setActive("jobs")}>My jobs</Button>
              <Button type="button" onClick={() => setActive(permissions?.reports?.canView ? "reports" : "time")}>{permissions?.reports?.canView ? "Daily reports" : "Time tracking"}</Button>
            </div>
          }
          tabs={tabs}
        />
        <div className="co-dashboard-kpi-grid mx-auto grid w-full max-w-[1520px] min-w-0 grid-cols-1 gap-3 px-5 pb-3 sm:px-6 md:grid-cols-4 lg:px-6">
          {fieldKpis.map((item) => <CommandCenterKpiCard key={item.label} item={item} />)}
        </div>
        <div className="co-dashboard-command-layout mx-auto grid w-full max-w-[1520px] min-w-0 gap-3 px-5 pb-4 sm:px-6 lg:px-6">
          <div className="co-dashboard-left-stack min-w-0 space-y-3">
            <Card className="co-dashboard-main-board overflow-hidden">
              <div className="co-dashboard-board-header border-b border-slate-200 bg-white p-4">
                <div className="flex min-w-0 flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                  <div className="min-w-0">
                    <h2>Field Operations Board</h2>
                    <p>Tap into assigned job work, reports, uploads, time, safety, and tool checks from one field-safe workspace.</p>
                  </div>
                  <Button type="button" size="sm" onClick={() => setActive("jobs")}>Open my jobs</Button>
                </div>
              </div>
              <div className="co-dashboard-field-actions p-4">
                <FieldActionGrid actions={fieldDashboardActions} onOpen={setActive} />
              </div>
            </Card>
            <div ref={jobsRef} tabIndex={-1} className="min-w-0 rounded-[inherit] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2">
              <Card className="co-dashboard-main-board overflow-hidden">
                <div className="co-dashboard-board-header border-b border-slate-200 bg-white p-4">
                  <div className="min-w-0">
                    <h2>Visible Jobs</h2>
                    <p>Only assigned and field-visible jobs appear here.</p>
                  </div>
                </div>
                {visibleJobRows.length ? (
                  <JobsTablePolished rows={visibleJobRows} selectedId={selectedJobId} onSelect={onSelectJob} maxRows={visibleJobRowCap} />
                ) : (
                  <div className="p-4">
                    <StateCard title="No field-visible jobs" description="Assigned jobs will appear here when the office makes them visible to this role." tone="slate" />
                  </div>
                )}
                <div className="co-dashboard-board-footer">
                  <p>Showing {Math.min(liveJobsPreview.length, visibleJobRowCap)} of {liveJobsPreview.length} visible jobs</p>
                  <Button type="button" size="sm" variant="secondary" onClick={() => setActive("jobs")}>Open jobs</Button>
                </div>
              </Card>
            </div>
          </div>
        </div>
        {showBackTop ? <button type="button" className="co-dashboard-back-top" onClick={scrollDashboardTop}>Top</button> : null}
      </div>
    );
  }

  return (
    <div className="co-office-page co-dashboard-page">
      <PageHeader
        eyebrow="Operations Command"
        title="Dashboard"
        description="Daily operator console for live leads, startup readiness, job movement, task queue, and activity."
        actions={
          <div className="co-dashboard-header-actions flex flex-wrap gap-2">
            {permissions?.jobs?.canManageAll ? <Button type="button" variant="secondary" onClick={() => setActive("commandCenter")}>Command Center</Button> : null}
            <Button type="button" variant="secondary" onClick={() => setActive("leads")}>Open leads</Button>
            <Button type="button" onClick={() => setActive("jobs")}>Open jobs</Button>
          </div>
        }
        tabs={tabs}
      />

      <div className="co-dashboard-kpi-grid mx-auto grid w-full max-w-[1520px] min-w-0 grid-cols-1 gap-3 px-5 pb-3 sm:px-6 md:grid-cols-5 lg:px-6">
        {dashboardKpis.map((item) => <CommandCenterKpiCard key={item.label} item={item} />)}
      </div>

      <div className="co-dashboard-priority-grid mx-auto grid w-full max-w-[1520px] min-w-0 grid-cols-1 gap-3 px-5 pb-3 sm:px-6 md:grid-cols-2 xl:grid-cols-4 lg:px-6">
        {dashboardPriorityCards.map((item) => <DashboardPriorityCard key={item.title} item={item} />)}
      </div>

      <div className="co-dashboard-command-layout mx-auto grid w-full max-w-[1520px] min-w-0 gap-3 px-5 pb-4 sm:px-6 lg:grid-cols-[minmax(0,1fr)_360px] lg:px-6">
        <div className="co-dashboard-left-stack min-w-0 space-y-3">
          <div ref={leadPipelineRef} tabIndex={-1} className="min-w-0 rounded-[inherit] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2">
            <Card className="co-dashboard-main-board overflow-hidden">
              <div className="co-dashboard-board-header border-b border-slate-200 bg-white p-4">
                <div className="flex min-w-0 flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
                  <div className="min-w-0">
                    <h2>Lead Pipeline Board</h2>
                    <p>Filter live opportunities, select a record, and keep the selected lead summary in the rail.</p>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <Button type="button" size="sm" variant="secondary" onClick={() => { setLeadFilter("All"); setLeadSearch(""); }}>Clear filters</Button>
                    <Button type="button" size="sm" onClick={() => setActive("leads")}>Manage leads</Button>
                  </div>
                </div>
              </div>
              <FilterBar filters={["All", "New", "Site Visit", "Estimate Sent", "Approved", "Archived"]} active={leadFilter} setActive={setLeadFilter} search={leadSearch} setSearch={setLeadSearch} placeholder="Search customer, project, city..." />
              {visibleLeads.length ? (
                <LeadsTable rows={visibleLeads} selectedId={selectedLeadId} onSelect={onSelectLead} maxRows={visibleLeadRowCap} />
              ) : (
                <div className="p-4">
                  <StateCard title="No leads match this view" description="Adjust filters or open Leads to add and manage opportunities." tone="blue" />
                </div>
              )}
              <div className="co-dashboard-board-footer">
                <p>Showing {Math.min(visibleLeads.length, visibleLeadRowCap)} of {visibleLeads.length} matching leads</p>
                <Button type="button" size="sm" variant="secondary" onClick={() => setActive("leads")}>Open full lead board</Button>
              </div>
            </Card>
          </div>

          <div ref={jobsRef} tabIndex={-1} className="min-w-0 rounded-[inherit] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2">
            <Card className="co-dashboard-main-board overflow-hidden">
              <div className="co-dashboard-board-header border-b border-slate-200 bg-white p-4">
                <div className="flex min-w-0 flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
                  <div className="min-w-0">
                    <h2>Active Jobs Snapshot</h2>
                    <p>Current work, schedule, foreman ownership, startup status, and next action.</p>
                  </div>
                  <Button type="button" size="sm" onClick={() => setActive("jobs")}>Open jobs</Button>
                </div>
              </div>
              {visibleJobRows.length ? (
                <JobsTablePolished rows={liveJobsPreview} selectedId={selectedJobId} onSelect={onSelectJob} maxRows={visibleJobRowCap} />
              ) : (
                <div className="p-4">
                  <StateCard title="No active jobs in preview" description="Jobs appear here when the current dashboard metrics include live work." tone="slate" />
                </div>
              )}
              <div className="co-dashboard-board-footer">
                <p>Showing {Math.min(liveJobsPreview.length, visibleJobRowCap)} of {liveJobsPreview.length} preview jobs</p>
                <Button type="button" size="sm" variant="secondary" onClick={() => setActive("jobs")}>Open job command board</Button>
              </div>
            </Card>
          </div>

          <DashboardOfficeQueueCard
            items={activeQueueItems}
            openCount={openQueueCount}
            onToggleTask={onToggleTask}
            onArchiveTask={onArchiveTask}
            onOpenTools={() => openDashboardTools(queueRef)}
            disabled={busy}
          />

          <details className="co-dashboard-tools-drawer" open={showOfficeTools} onToggle={(event) => setShowOfficeTools(event.currentTarget.open)}>
            <summary>
              <span>
                <strong>Operator Tools</strong>
                <em>Full task queue, add-task form, and selected lead editing stay here when deeper work is needed.</em>
              </span>
              <span>{openQueueCount} open queue item{openQueueCount === 1 ? "" : "s"}</span>
            </summary>
            <div className="co-dashboard-tools-panel grid gap-3 xl:grid-cols-[minmax(0,0.88fr)_minmax(0,1.12fr)]">
              <div ref={queueRef} tabIndex={-1} className="min-w-0 rounded-[inherit] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2">
                <QueueList items={queueItems} onToggleTask={onToggleTask} onArchiveTask={onArchiveTask} onRestoreTask={onRestoreTask} onDeleteTask={onDeleteTask} taskDraft={taskDraft} setTaskDraft={setTaskDraft} onAddTask={onAddTask} disabled={busy} />
              </div>
              <LeadDetailPanel lead={selectedLead} onFieldChange={onLeadFieldChange} onScoreLead={onScoreLead} onCheckMissingInfo={onCheckMissingInfo} onGenerateLeadAssistant={onGenerateLeadAssistant} leadAssistantState={leadAssistantState} onCreateJob={onCreateJobFromLead} onCreateEstimateFromLead={onCreateEstimateFromLead} onConvertToCustomer={onConvertLeadToCustomer} onArchive={onArchiveLead} onRestore={onRestoreLead} onDelete={onDeleteLead} onSelectCustomer={onSelectCustomer} related={relatedLeadRecords} users={users} customers={customers} contactHistory={contactHistory} contactHistoryPermissions={permissions.contactHistory} onCreateContactHistory={onCreateContactHistory} onUpdateContactHistory={onUpdateContactHistory} onArchiveContactHistory={onArchiveContactHistory} onRestoreContactHistory={onRestoreContactHistory} disabled={busy} saveState={leadSaveState} canManage={permissions.leads.canManage} canCreateEstimate={permissions?.estimates?.canManage} />
            </div>
          </details>

          <details className="co-dashboard-tools-drawer">
            <summary>
              <span>
                <strong>Pilot Flow / Team Activity</strong>
                <em>Secondary workflow guidance and activity stay one click away.</em>
              </span>
              <span>{normalizeObjectArray(activity).length} activity item{normalizeObjectArray(activity).length === 1 ? "" : "s"}</span>
            </summary>
            <div className="co-dashboard-tools-panel grid gap-3 xl:grid-cols-[minmax(0,1fr)_minmax(0,0.9fr)]">
              {permissions?.jobs?.canManageAll ? (
                <OfficePilotWalkthroughCard
                  onOpenCommandCenter={() => setActive("commandCenter")}
                  onOpenDrafts={() => setActive("jobDraftImports")}
                  onOpenJobs={() => setActive("jobs")}
                />
              ) : null}
              <ActivityPanel activity={activity} />
            </div>
          </details>
        </div>

        <DashboardCommandRailPolished
          stats={stats}
          selectedLead={selectedLead}
          liveJobsPreview={liveJobsPreview}
          queueItems={queueItems}
          activity={activity}
          permissions={permissions}
          setActive={setActive}
          onFocusQueue={() => focusDashboardRef(queueRef)}
          onFocusJobs={() => focusDashboardRef(jobsRef)}
          onFocusLeads={() => focusDashboardRef(leadPipelineRef)}
        />
      </div>
      {showBackTop ? <button type="button" className="co-dashboard-back-top" onClick={scrollDashboardTop}>Top</button> : null}
    </div>
  );
}

function leadSourceLabel(source) {
  return source === "public_request_form" ? "Public request form" : source;
}

function leadContactPhone(lead = {}) {
  return lead.phone || lead.contactPhone || lead.customerPhone || lead.primaryPhone || "";
}

function leadContactEmail(lead = {}) {
  return lead.email || lead.contactEmail || lead.customerEmail || lead.primaryEmail || "";
}

function formatLeadFollowUpDate(value) {
  if (!value) return "Not set";
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return String(value);
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(parsed);
}

function isLeadFollowUpDue(lead = {}, today = todayDateInputValue()) {
  if (!lead.followUpDueAt) return false;
  return String(lead.followUpDueAt).slice(0, 10) <= today;
}

function isLeadWaitingOnResponse(lead = {}) {
  const status = String(lead.status || "").toLowerCase();
  const nextStep = String(lead.nextStep || "").toLowerCase();
  return status.includes("waiting") || nextStep.includes("waiting") || nextStep.includes("response");
}

function isLeadReadyForEstimate(lead = {}) {
  const status = String(lead.status || "").toLowerCase();
  const nextStep = String(lead.nextStep || "").toLowerCase();
  return status.includes("site visit") || status.includes("estimate") || nextStep.includes("estimate") || nextStep.includes("proposal");
}

function leadHasScore(lead = {}) {
  return Boolean(lead.scoredAt || lead.scoreSource || lead.fitLabel);
}

function leadHasMissingInfoCheck(lead = {}) {
  return Boolean(lead.missingInfoCheckedAt || lead.missingInfoStatus);
}

function LeadScoreBadge({ lead }) {
  if (!leadHasScore(lead)) return <Badge tone="slate">Not scored</Badge>;
  return <Badge tone={leadScoreTone(lead.fitLabel || lead.fitScore)}>{Number(lead.fitScore || 0)} / {lead.fitLabel || "Scored"}</Badge>;
}

function LeadMissingInfoBadge({ lead }) {
  if (!leadHasMissingInfoCheck(lead)) return <Badge tone="slate">Info not checked</Badge>;
  const count = Number(lead.missingInfoCount || 0);
  const label = lead.missingInfoStatus === "Complete" ? "Info complete" : `Needs ${count} item${count === 1 ? "" : "s"}`;
  return <Badge tone={missingInfoTone(lead.missingInfoStatus || count)}>{label}</Badge>;
}

function LeadScoreCard({ lead, canManage = false, disabled = false, onScoreLead = () => {} }) {
  const hasScore = leadHasScore(lead);
  const risks = Array.isArray(lead?.fitRisks) ? lead.fitRisks : [];
  return (
    <div className="rounded-3xl border border-blue-100 bg-blue-50/60 p-4">
      <div className="flex min-w-0 flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-2">
            <p className="text-sm font-black text-slate-950">Rule-based lead score</p>
            <LeadScoreBadge lead={lead} />
            {hasScore ? <Badge tone="slate">Rule-Based</Badge> : null}
          </div>
          <p className="mt-1 text-sm leading-6 text-slate-600">
            {hasScore ? lead.fitReason || "Local rules scored this lead." : "Score this lead with local business rules. No AI, scraping, or external calls are used."}
          </p>
        </div>
        {canManage ? (
          <Button type="button" className="w-full sm:w-auto" onClick={() => onScoreLead(lead)} disabled={disabled || Boolean(lead.archivedAt)}>
            {hasScore ? "Re-score Lead" : "Score Lead"}
          </Button>
        ) : null}
      </div>
      {hasScore ? (
        <div className="mt-3 grid gap-3 md:grid-cols-2">
          <div className="rounded-2xl border border-blue-100 bg-white p-3">
            <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">Recommended next step</p>
            <p className="mt-1 text-sm font-bold leading-6 text-slate-700">{lead.fitNextStep || "Review and choose the next office step."}</p>
          </div>
          <div className="rounded-2xl border border-blue-100 bg-white p-3">
            <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">Risks / missing info</p>
            {risks.length > 0 ? (
              <ul className="mt-1 space-y-1 text-sm font-bold leading-6 text-slate-700">
                {risks.slice(0, 4).map((risk) => <li key={risk}>- {risk}</li>)}
              </ul>
            ) : (
              <p className="mt-1 text-sm font-bold text-emerald-700">No major rule-based risks found.</p>
            )}
          </div>
          <p className="text-xs font-bold text-slate-500 md:col-span-2">Scored {formatDateTime(lead.scoredAt)}. Scores are office-only and based on saved lead/source fields.</p>
        </div>
      ) : null}
    </div>
  );
}

function LeadMissingInfoCard({ lead, canManage = false, disabled = false, onCheckMissingInfo = () => {} }) {
  const hasCheck = leadHasMissingInfoCheck(lead);
  const items = Array.isArray(lead?.missingInfoItems) ? lead.missingInfoItems : [];
  const required = items.filter((item) => item.severity === "required");
  const recommended = items.filter((item) => item.severity === "recommended");
  const optional = items.filter((item) => item.severity === "optional");

  function MissingGroup({ title, rows, tone }) {
    if (rows.length === 0) return null;
    return (
      <div className="rounded-2xl border border-blue-100 bg-white p-3">
        <div className="mb-2 flex items-center justify-between gap-2">
          <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">{title}</p>
          <Badge tone={tone}>{rows.length}</Badge>
        </div>
        <div className="space-y-2">
          {rows.slice(0, 5).map((item) => (
            <div key={item.key} className="rounded-2xl border border-blue-50 bg-blue-50/50 p-3">
              <p className="text-sm font-black text-slate-950">{item.label}</p>
              <p className="mt-1 text-xs font-bold leading-5 text-slate-600">{item.reason}</p>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="rounded-3xl border border-amber-100 bg-amber-50/60 p-4">
      <div className="flex min-w-0 flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-2">
            <p className="text-sm font-black text-slate-950">Missing Info Checker</p>
            <LeadMissingInfoBadge lead={lead} />
            <Badge tone="slate">Rule-Based</Badge>
          </div>
          <p className="mt-1 text-sm leading-6 text-slate-600">
            {hasCheck ? lead.missingInfoNextStep || "Review missing lead details before estimating." : "Check required and recommended lead details before spending time estimating or following up."}
          </p>
        </div>
        {canManage ? (
          <Button type="button" className="w-full sm:w-auto" onClick={() => onCheckMissingInfo(lead)} disabled={disabled || Boolean(lead.archivedAt)}>
            {hasCheck ? "Re-check Missing Info" : "Check Missing Info"}
          </Button>
        ) : null}
      </div>
      {hasCheck ? (
        <div className="mt-3 space-y-3">
          {lead.missingInfoStatus === "Needs Info" ? (
            <p className="rounded-2xl border border-amber-100 bg-white px-3 py-2 text-sm font-black text-amber-800">Fill missing info before estimating.</p>
          ) : (
            <p className="rounded-2xl border border-emerald-100 bg-white px-3 py-2 text-sm font-black text-emerald-800">Core lead info is complete enough for office follow-up or estimating.</p>
          )}
          <div className="grid gap-3 lg:grid-cols-3">
            <MissingGroup title="Required" rows={required} tone="red" />
            <MissingGroup title="Recommended" rows={recommended} tone="amber" />
            <MissingGroup title="Optional" rows={optional} tone="slate" />
          </div>
          {items.length === 0 ? <p className="text-sm font-bold text-emerald-700">No missing items found.</p> : null}
          <p className="text-xs font-bold text-slate-500">Checked {formatDateTime(lead.missingInfoCheckedAt)}. Missing info checks are office-only and use saved lead/source fields.</p>
        </div>
      ) : null}
    </div>
  );
}

function LeadAiAssistantCard({ lead, canManage = false, disabled = false, assistant = null, onGenerateLeadAssistant = () => {} }) {
  const [copyMessage, setCopyMessage] = useState("");
  if (!canManage) return null;

  const result = assistant?.result || null;
  const loading = Boolean(assistant?.loading);
  const message = assistant?.error || result?.message || "";
  const generated = Boolean(result?.configured && result?.ok);
  const unavailable = Boolean(message && !generated);

  async function copyText(label, value) {
    if (!value) return;
    if (typeof navigator === "undefined" || !navigator.clipboard?.writeText) {
      setCopyMessage("Copy is not available in this browser. Select the draft text and copy it manually.");
      return;
    }
    await navigator.clipboard.writeText(value);
    setCopyMessage(`${label} copied.`);
  }

  function DraftBlock({ title, value, copyLabel }) {
    if (!value) return null;
    return (
      <div className="rounded-2xl border border-blue-100 bg-white p-3">
        <div className="flex min-w-0 flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
          <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">{title}</p>
          <Button type="button" size="sm" variant="secondary" onClick={() => copyText(copyLabel || title, value)}>Copy</Button>
        </div>
        <p className="mt-2 whitespace-pre-wrap text-sm font-bold leading-6 text-slate-700">{value}</p>
      </div>
    );
  }

  return (
    <div className="rounded-3xl border border-sky-100 bg-sky-50/60 p-4">
      <div className="flex min-w-0 flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-2">
            <p className="text-sm font-black text-slate-950">AI Lead Assistant</p>
            <Badge tone="blue">Draft only</Badge>
            <Badge tone="slate">Office review</Badge>
          </div>
          <p className="mt-1 text-sm leading-6 text-slate-600">
            Generate review-only lead help: summary, next step, missing info questions, email/SMS drafts, call script, and estimating handoff notes. Nothing is sent.
          </p>
        </div>
        <Button type="button" className="w-full sm:w-auto" onClick={() => onGenerateLeadAssistant(lead)} disabled={disabled || loading || Boolean(lead.archivedAt)}>
          {loading ? "Generating..." : generated ? "Regenerate" : "Generate AI Lead Drafts"}
        </Button>
      </div>

      {unavailable ? (
        <p className="mt-3 rounded-2xl border border-amber-100 bg-white px-3 py-2 text-sm font-bold text-amber-800">{message}</p>
      ) : null}

      {generated ? (
        <div className="mt-3 space-y-3">
          <div className="grid gap-3 lg:grid-cols-2">
            <div className="rounded-2xl border border-blue-100 bg-white p-3">
              <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">AI summary</p>
              <p className="mt-2 text-sm font-bold leading-6 text-slate-700">{result.leadSummary || "Review the lead details before follow-up."}</p>
            </div>
            <div className="rounded-2xl border border-blue-100 bg-white p-3">
              <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">Recommended next step</p>
              <p className="mt-2 text-sm font-bold leading-6 text-slate-700">{result.recommendedNextStep || "Choose the next office action."}</p>
              {result.suggestedFollowUpTiming ? <p className="mt-2 text-xs font-bold text-slate-500">Suggested timing: {result.suggestedFollowUpTiming}</p> : null}
              {result.suggestedStatus ? <Badge tone="blue">{result.suggestedStatus}</Badge> : null}
            </div>
          </div>

          {Array.isArray(result.missingInfoQuestions) && result.missingInfoQuestions.length > 0 ? (
            <div className="rounded-2xl border border-blue-100 bg-white p-3">
              <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">Missing info questions</p>
              <ul className="mt-2 space-y-1 text-sm font-bold leading-6 text-slate-700">
                {result.missingInfoQuestions.map((question) => <li key={question}>- {question}</li>)}
              </ul>
            </div>
          ) : null}

          <div className="grid gap-3 xl:grid-cols-2">
            <DraftBlock title="Follow-up email draft" value={result.followUpEmailDraft} copyLabel="Email draft" />
            <DraftBlock title="SMS/text draft" value={result.followUpSmsDraft} copyLabel="SMS draft" />
            <DraftBlock title="Call script" value={result.callScript} copyLabel="Call script" />
            <DraftBlock title="Estimating handoff notes" value={result.estimatingHandoffNotes} copyLabel="Estimating handoff notes" />
          </div>

          {Array.isArray(result.riskNotes) && result.riskNotes.length > 0 ? (
            <div className="rounded-2xl border border-amber-100 bg-white p-3">
              <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">Risk notes</p>
              <ul className="mt-2 space-y-1 text-sm font-bold leading-6 text-amber-800">
                {result.riskNotes.map((risk) => <li key={risk}>- {risk}</li>)}
              </ul>
            </div>
          ) : null}

          <p className="text-xs font-bold text-slate-500">AI drafts are review-only. Apex HQ does not send emails or texts from this card.</p>
          {copyMessage ? <p className="rounded-2xl border border-emerald-100 bg-white px-3 py-2 text-sm font-bold text-emerald-700">{copyMessage}</p> : null}
        </div>
      ) : null}
    </div>
  );
}

function LeadInboxReviewQueue({ inboxState, onSelectLead, onCreateEstimateFromLead = () => {}, onScoreLead = () => {}, onCheckMissingInfo = () => {}, canManage = false, canCreateEstimate = false, disabled = false }) {
  const stats = [
    { label: "New / Needs Review", value: inboxState.stats.newNeedsReview, tone: "blue" },
    { label: "Follow-Up Due", value: inboxState.stats.followUpDue, tone: "amber" },
    { label: "Missing Next Step", value: inboxState.stats.missingNextStep, tone: "amber" },
    { label: "Ready for Estimate", value: inboxState.stats.readyForEstimate, tone: "green" },
  ];
  const queueItems = inboxState.items.slice(0, 4);

  return (
    <Card className="p-4">
      <div className="flex min-w-0 flex-col gap-4 xl:flex-row xl:items-start xl:justify-between">
        <div className="min-w-0">
          <Badge tone="blue">Lead Inbox / Review Queue</Badge>
          <h3 className="mt-2 text-base font-black text-slate-950">Review these leads first</h3>
          <p className="mt-1 text-sm leading-6 text-slate-600">
            A simple landing zone for newly found, call-in, and follow-up leads before they become estimates.
          </p>
        </div>
        <div className="grid min-w-0 gap-2 sm:grid-cols-2 xl:min-w-[520px] xl:grid-cols-4">
          {stats.map((item) => (
            <div key={item.label} className="rounded-2xl border border-blue-100 bg-blue-50/50 p-3">
              <p className="text-xl font-black text-slate-950">{item.value}</p>
              <Badge tone={item.value > 0 ? item.tone : "slate"}>{item.label}</Badge>
            </div>
          ))}
        </div>
      </div>
      <div className="mt-3 grid gap-2 xl:grid-cols-2">
        {queueItems.length > 0 ? queueItems.map((lead) => (
          <div key={lead.id} className="rounded-xl border border-blue-100 bg-white p-3 shadow-sm">
            <div className="flex min-w-0 flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
              <div className="min-w-0">
                <p className="break-words text-sm font-black text-slate-950">{lead.customer || "Unnamed lead"}</p>
                <p className="mt-1 break-words text-xs font-bold text-slate-500">
                  {[lead.project, lead.city || lead.state, leadSourceLabel(lead.source || "Call-in")].filter(Boolean).join(" / ")}
                </p>
                <div className="mt-2 flex flex-wrap gap-1.5">
                  {lead.reviewReasons.map((reason) => <Badge key={reason.label} tone={reason.tone}>{reason.label}</Badge>)}
                  <LeadScoreBadge lead={lead} />
                  <LeadMissingInfoBadge lead={lead} />
                </div>
              </div>
              <div className="grid w-full grid-cols-2 gap-2 sm:w-auto sm:min-w-[10rem]">
                <Button type="button" size="sm" variant="secondary" onClick={() => onSelectLead?.(lead.id)}>Review lead</Button>
                {canManage ? <Button type="button" size="sm" variant="secondary" onClick={() => onCheckMissingInfo(lead)} disabled={disabled || Boolean(lead.archivedAt)}>{leadHasMissingInfoCheck(lead) ? "Re-check info" : "Check info"}</Button> : null}
                {canManage ? <Button type="button" size="sm" variant="secondary" onClick={() => onScoreLead(lead)} disabled={disabled || Boolean(lead.archivedAt)}>{leadHasScore(lead) ? "Re-score" : "Score"}</Button> : null}
                {canCreateEstimate && lead.reviewReasons.some((reason) => reason.label === "Ready for Estimate") ? (
                  <Button type="button" size="sm" onClick={() => onCreateEstimateFromLead(lead)}>Create Estimate</Button>
                ) : null}
              </div>
            </div>
            <p className="mt-2 line-clamp-2 text-xs font-bold leading-5 text-slate-600">{lead.nextStep || lead.reviewReasons[0]?.helper || "Add a next step before this lead moves forward."}</p>
          </div>
        )) : (
          <StateCard title="Lead inbox is clear" description="New leads, due follow-ups, missing next steps, and estimate-ready leads will appear here." tone="slate" />
        )}
      </div>
    </Card>
  );
}

function ManualOutreachDraftPanel({
  item,
  companyName,
  user,
  disabled = false,
  onClose = () => {},
  onAction = async () => false,
}) {
  const drafts = useMemo(() => buildManualOutreachDrafts(item || {}, {
    companyName,
    senderName: user?.name || companyName,
  }), [companyName, item, user?.name]);
  const [copyMessage, setCopyMessage] = useState("");

  if (!item || item.type === "leadSource") return null;

  async function copyText(label, value) {
    if (!value) return;
    try {
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(value);
      } else {
        const textarea = document.createElement("textarea");
        textarea.value = value;
        textarea.setAttribute("readonly", "true");
        textarea.style.position = "fixed";
        textarea.style.left = "-9999px";
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand("copy");
        document.body.removeChild(textarea);
      }
      setCopyMessage(`${label} copied.`);
    } catch {
      setCopyMessage("Could not copy automatically. Select the text below and copy manually.");
    }
  }

  function DraftBlock({ title, value, copyLabel, rows = 5 }) {
    return (
      <div className="rounded-2xl border border-blue-100 bg-white p-3">
        <div className="flex min-w-0 flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <p className="text-sm font-black text-slate-950">{title}</p>
            <p className="mt-1 text-xs font-bold text-slate-500">Manual copy only — no message is sent from Apex HQ.</p>
          </div>
          <Button type="button" size="sm" variant="secondary" onClick={() => copyText(copyLabel, value)} disabled={disabled || !value}>Copy</Button>
        </div>
        <textarea
          className="field-input mt-3 min-h-[120px] whitespace-pre-wrap font-mono text-xs leading-5"
          readOnly
          rows={rows}
          value={value || ""}
          onFocus={(event) => event.currentTarget.select()}
        />
      </div>
    );
  }

  return (
    <div className="mt-4 rounded-3xl border border-amber-100 bg-amber-50/60 p-4">
      <div className="flex min-w-0 flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
        <div className="min-w-0">
          <Badge tone="amber">Draft / Copy</Badge>
          <h4 className="mt-2 text-base font-black text-slate-950">{item.title}</h4>
          <p className="mt-1 text-sm leading-6 text-slate-700">Manual copy only — Apex HQ does not send email, SMS, or calls from this panel.</p>
        </div>
        <Button type="button" size="sm" variant="ghost" onClick={onClose}>Close Drafts</Button>
      </div>

      {copyMessage ? <p className="mt-3 rounded-2xl border border-emerald-100 bg-white px-3 py-2 text-sm font-bold text-emerald-700">{copyMessage}</p> : null}

      <div className="mt-4 grid gap-3 xl:grid-cols-2">
        <DraftBlock title="Email subject" value={drafts.emailSubject} copyLabel="Email subject" rows={2} />
        <DraftBlock title="Email body" value={drafts.emailBody} copyLabel="Email body" />
        <DraftBlock title="SMS/text body" value={drafts.smsBody} copyLabel="SMS draft" rows={4} />
        <DraftBlock title="Call script" value={drafts.callScript} copyLabel="Call script" />
        <DraftBlock title="Voicemail script" value={drafts.voicemailScript} copyLabel="Voicemail script" rows={4} />
      </div>

      <div className="mt-4 flex flex-wrap gap-2">
        <Button type="button" size="sm" onClick={() => onAction(item, "mark-email-sent", drafts)} disabled={disabled}>Mark Email Manually Sent</Button>
        <Button type="button" size="sm" onClick={() => onAction(item, "mark-text-sent", drafts)} disabled={disabled}>Mark Text Manually Sent</Button>
        <Button type="button" size="sm" variant="secondary" onClick={() => onAction(item, "log-call", drafts)} disabled={disabled}>Log Call Attempt</Button>
        <Button type="button" size="sm" variant="secondary" onClick={() => onAction(item, "mark-waiting", drafts)} disabled={disabled}>Mark Waiting on Response</Button>
        <Button type="button" size="sm" variant="ghost" onClick={() => onAction(item, "follow-up-tomorrow", drafts)} disabled={disabled}>Follow-Up Tomorrow</Button>
        <Button type="button" size="sm" variant="ghost" onClick={() => onAction(item, "follow-up-two-days", drafts)} disabled={disabled}>Follow-Up in 2 Days</Button>
      </div>
    </div>
  );
}

function FollowUpQueuePanel({
  leads = [],
  customers = [],
  estimates = [],
  leadSources = [],
  contactHistory = [],
  permissions,
  companyName,
  user,
  disabled = false,
  onOpenLead = () => {},
  onOpenCustomer = () => {},
  onOpenEstimate = () => {},
  onOpenLeads = () => {},
  onCreateContactHistory = async () => false,
  compact = false,
  maxItems = 12,
}) {
  const canView = Boolean(permissions?.contactHistory?.canView && permissions?.leads?.canView);
  const canManage = Boolean(permissions?.contactHistory?.canManage);
  const [groupFilter, setGroupFilter] = useState("all");
  const [typeFilter, setTypeFilter] = useState("all");
  const [query, setQuery] = useState("");
  const [message, setMessage] = useState("");
  const [draftItemId, setDraftItemId] = useState("");
  const today = todayDateInputValue();
  const queueState = useMemo(() => deriveFollowUpQueueState({
    leads,
    customers,
    estimates,
    leadSources,
    contactHistory,
  }, { today }), [contactHistory, customers, estimates, leadSources, leads, today]);
  const visibleItems = useMemo(() => filterFollowUpQueueItems(queueState.items, {
    group: groupFilter,
    type: typeFilter,
    query,
  }), [groupFilter, query, queueState.items, typeFilter]);
  const draftItem = useMemo(() => queueState.items.find((item) => item.id === draftItemId) || null, [draftItemId, queueState.items]);

  if (!canView) return null;

  function openItem(item) {
    if (item.type === "lead") onOpenLead(item.recordId);
    else if (item.type === "customer") onOpenCustomer(item.recordId);
    else if (item.type === "estimate") onOpenEstimate(item.recordId);
    else onOpenLeads();
  }

  async function runQueueAction(item, action, drafts = null) {
    if (!canManage || disabled) return;
    if (item.type === "leadSource") {
      onOpenLeads();
      setMessage("Open the Daily Source Check card below to mark this source checked.");
      return;
    }

    const normalizedAction = action === "log-email" ? "mark-email-sent" : action === "log-text" ? "mark-text-sent" : action === "waiting" ? "mark-waiting" : action;
    const payload = buildManualOutreachContactPayload(item, normalizedAction, {
      today,
      drafts,
      companyName,
      senderName: user?.name || companyName,
    });
    if (!payload) return;
    const didSave = await onCreateContactHistory(payload);
    if (didSave) {
      const label = normalizedAction === "follow-up-tomorrow"
        ? "Follow-up moved to tomorrow."
        : normalizedAction === "follow-up-two-days"
          ? "Follow-up moved out two days."
          : normalizedAction === "mark-waiting"
            ? "Marked waiting on response."
            : normalizedAction === "mark-email-sent"
              ? "Manual email draft logged as sent outside Apex HQ."
              : normalizedAction === "mark-text-sent"
                ? "Manual text draft logged as sent outside Apex HQ."
                : "Manual outreach logged.";
      setMessage(`${label} No email or text was sent.`);
    }
  }

  const stats = [
    { label: "Due Today", value: queueState.stats.dueToday, tone: "amber" },
    { label: "Overdue", value: queueState.stats.overdue, tone: "red" },
    { label: "Waiting", value: queueState.stats.waiting, tone: "blue" },
    { label: "Not Contacted", value: queueState.stats.notContacted, tone: "slate" },
  ];
  const visibleDisplayItems = visibleItems.slice(0, maxItems);

  if (compact) {
    return (
      <Card className="co-leads-followup-card co-leads-followup-compact overflow-hidden">
        <div className="co-leads-followup-header border-b border-slate-200 bg-white p-3">
          <div className="flex min-w-0 flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
            <div className="min-w-0">
              <h3 className="text-sm font-black uppercase tracking-[0.06em] text-slate-950">Follow-Up Queue / Office Action Board</h3>
              <p className="mt-1 text-xs font-bold leading-5 text-slate-600">Work the next calls, manual drafts, waiting records, and due follow-ups without opening every lead tool.</p>
            </div>
            <div className="co-leads-followup-stat-grid grid min-w-0 grid-cols-2 gap-2 sm:grid-cols-4 xl:min-w-[430px]">
              {stats.map((stat) => (
                <div key={stat.label} className="co-leads-followup-stat">
                  <p>{stat.value}</p>
                  <span>{stat.label}</span>
                </div>
              ))}
            </div>
          </div>
          <div className="co-leads-followup-tabs mt-3 flex min-w-0 gap-2 overflow-x-auto pb-1">
            {FOLLOW_UP_QUEUE_GROUPS.slice(0, 7).map((group) => (
              <button
                key={group.id}
                type="button"
                className={groupFilter === group.id ? "is-active" : ""}
                onClick={() => setGroupFilter(group.id)}
              >
                {group.label}
              </button>
            ))}
          </div>
          {message ? <p className="mt-2 rounded-xl border border-emerald-100 bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-700">{message}</p> : null}
          <ManualOutreachDraftPanel
            item={draftItem}
            companyName={companyName}
            user={user}
            disabled={disabled}
            onClose={() => setDraftItemId("")}
            onAction={runQueueAction}
          />
        </div>

        <div className="hidden md:block">
          <div className="table-shell co-leads-followup-table-shell">
            <table className="co-leads-followup-table w-full min-w-[860px] text-left">
              <thead>
                <tr>
                  <th>Customer / Company</th>
                  <th>Last Contact</th>
                  <th>Next Step</th>
                  <th>Status</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {visibleDisplayItems.map((item) => (
                  <tr key={item.id}>
                    <td>
                      <p className="font-black text-slate-950">{item.title}</p>
                      <p className="text-xs font-bold text-slate-500">{item.subtitle || item.type}</p>
                    </td>
                    <td className="text-sm font-bold text-slate-700">{item.lastContactedAt ? formatDateTime(item.lastContactedAt) : "Not contacted"}</td>
                    <td className="text-sm font-bold text-slate-700"><span className="line-clamp-2">{item.notesPreview || item.reason || "Review next action"}</span></td>
                    <td><Badge tone={item.bucket === "overdue" ? "red" : item.bucket === "dueToday" ? "amber" : item.bucket === "waiting" ? "blue" : "slate"}>{FOLLOW_UP_QUEUE_GROUPS.find((group) => group.id === item.bucket)?.label || "Follow-Up"}</Badge></td>
                    <td>
                      <div className="flex justify-end gap-2">
                        <button type="button" className="co-leads-row-action" onClick={() => openItem(item)}>{item.actionLabel}</button>
                        {canManage && item.type !== "leadSource" ? <button type="button" className="co-leads-row-action" onClick={() => setDraftItemId(item.id)} disabled={disabled}>Draft / Copy</button> : null}
                        {canManage && item.type !== "leadSource" ? <button type="button" className="co-leads-icon-button" onClick={() => runQueueAction(item, "mark-waiting")} disabled={disabled} aria-label={`Mark ${item.title} waiting`}><Icon name="clock" /></button> : null}
                        {canManage && item.type !== "leadSource" ? <button type="button" className="co-leads-icon-button" onClick={() => runQueueAction(item, "follow-up-tomorrow")} disabled={disabled} aria-label={`Follow up with ${item.title} tomorrow`}><Icon name="clipboard" /></button> : null}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="co-leads-followup-mobile-list grid gap-2 p-3 md:hidden">
          {visibleDisplayItems.map((item) => (
            <div key={item.id} className="co-office-list-card rounded-xl border border-slate-200 bg-white p-3">
              <div className="flex min-w-0 items-start justify-between gap-3">
                <div className="min-w-0">
                  <p className="break-words text-sm font-black text-slate-950">{item.title}</p>
                  <p className="mt-1 break-words text-xs font-bold text-slate-500">{item.subtitle || item.reason}</p>
                </div>
                <Badge tone={item.bucket === "overdue" ? "red" : item.bucket === "dueToday" ? "amber" : item.bucket === "waiting" ? "blue" : "slate"}>{FOLLOW_UP_QUEUE_GROUPS.find((group) => group.id === item.bucket)?.label || "Follow-Up"}</Badge>
              </div>
              <div className="mt-3 grid grid-cols-2 gap-2">
                <Button type="button" size="sm" variant="secondary" onClick={() => openItem(item)}>{item.actionLabel}</Button>
                {canManage && item.type !== "leadSource" ? <Button type="button" size="sm" onClick={() => setDraftItemId(item.id)} disabled={disabled}>Draft / Copy</Button> : null}
              </div>
            </div>
          ))}
          {visibleDisplayItems.length === 0 ? <StateCard title="Follow-up queue is clear" description="Due, overdue, waiting, not-contacted, and recently contacted records will appear here." tone="slate" /> : null}
        </div>

        <details className="co-leads-tool-disclosure co-leads-followup-filters mx-3 mb-3">
          <summary>
            <span>Search and queue filters</span>
            <span>{visibleItems.length} matching records</span>
          </summary>
          <div className="mt-3 grid gap-3 lg:grid-cols-[minmax(0,1fr)_220px_220px]">
            <input
              className="field-input"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Search follow-ups, customers, projects, notes..."
            />
            <SelectField label="Queue" value={groupFilter} onChange={(event) => setGroupFilter(event.target.value)}>
              {FOLLOW_UP_QUEUE_GROUPS.map((group) => <option key={group.id} value={group.id}>{group.label}</option>)}
            </SelectField>
            <SelectField label="Type" value={typeFilter} onChange={(event) => setTypeFilter(event.target.value)}>
              {FOLLOW_UP_QUEUE_TYPE_FILTERS.map((type) => <option key={type.id} value={type.id}>{type.label}</option>)}
            </SelectField>
          </div>
        </details>

        <div className="co-leads-followup-footer flex min-w-0 flex-wrap items-center justify-between gap-2 border-t border-slate-200 bg-white px-3 py-2">
          <p className="text-xs font-black text-slate-500">Showing {visibleDisplayItems.length} of {visibleItems.length} follow-up records.</p>
          <button type="button" className="text-xs font-black text-orange-700" onClick={() => setGroupFilter("all")}>View all follow-up work</button>
        </div>
      </Card>
    );
  }

  return (
    <Card className="overflow-hidden">
      <div className="border-b border-blue-100 bg-white p-4">
        <div className="flex min-w-0 flex-col gap-4 xl:flex-row xl:items-start xl:justify-between">
          <div className="min-w-0">
            <Badge tone="amber">Follow-Up Queue</Badge>
            <h3 className="mt-2 text-base font-black text-slate-950">Manual outreach queue</h3>
            <p className="mt-1 text-sm leading-6 text-slate-600">
              Leads, customers, estimates, and source checks needing office attention. No emails or texts are sent from here.
            </p>
          </div>
          <div className="grid min-w-0 gap-2 sm:grid-cols-4 xl:min-w-[560px]">
            {stats.map((stat) => (
              <div key={stat.label} className="rounded-2xl border border-blue-100 bg-blue-50/50 p-3">
                <p className="text-lg font-black text-slate-950">{stat.value}</p>
                <Badge tone={stat.value > 0 ? stat.tone : "slate"}>{stat.label}</Badge>
              </div>
            ))}
          </div>
        </div>
        {message ? <p className="mt-3 rounded-2xl border border-emerald-100 bg-emerald-50 px-3 py-2 text-sm font-bold text-emerald-700">{message}</p> : null}
        <ManualOutreachDraftPanel
          item={draftItem}
          companyName={companyName}
          user={user}
          disabled={disabled}
          onClose={() => setDraftItemId("")}
          onAction={runQueueAction}
        />
        <div className="mt-4 grid gap-3 lg:grid-cols-[minmax(0,1fr)_220px_220px]">
          <input
            className="field-input"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search follow-ups, customers, projects, notes..."
          />
          <SelectField label="Queue" value={groupFilter} onChange={(event) => setGroupFilter(event.target.value)}>
            {FOLLOW_UP_QUEUE_GROUPS.map((group) => <option key={group.id} value={group.id}>{group.label}</option>)}
          </SelectField>
          <SelectField label="Type" value={typeFilter} onChange={(event) => setTypeFilter(event.target.value)}>
            {FOLLOW_UP_QUEUE_TYPE_FILTERS.map((type) => <option key={type.id} value={type.id}>{type.label}</option>)}
          </SelectField>
        </div>
      </div>

      <div className="grid gap-3 p-4">
        {visibleItems.length > 0 ? visibleDisplayItems.map((item) => (
          <div key={item.id} className="rounded-2xl border border-blue-100 bg-white p-4 shadow-sm">
            <div className="flex min-w-0 flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
              <div className="min-w-0">
                <div className="flex flex-wrap items-center gap-2">
                  <p className="break-words text-sm font-black text-slate-950">{item.title}</p>
                  <Badge tone={item.bucket === "overdue" ? "red" : item.bucket === "dueToday" ? "amber" : item.bucket === "waiting" ? "blue" : "slate"}>{FOLLOW_UP_QUEUE_GROUPS.find((group) => group.id === item.bucket)?.label || "Follow-Up"}</Badge>
                  <Badge tone="slate">{item.type === "leadSource" ? "Lead Source" : item.type[0].toUpperCase() + item.type.slice(1)}</Badge>
                </div>
                <p className="mt-1 break-words text-xs font-bold text-slate-500">{item.subtitle || "No extra context"}</p>
                <p className="mt-2 text-sm leading-6 text-slate-600">{item.reason}</p>
                <div className="mt-3 flex flex-wrap gap-2 text-xs font-bold text-slate-500">
                  <span>Last: {item.lastContactedAt ? formatDateTime(item.lastContactedAt) : "Not contacted"}</span>
                  <span>Next: {item.nextFollowUpDate || "Not scheduled"}</span>
                  {item.lastContactMethod ? <span>Method: {item.lastContactMethod}</span> : null}
                  {item.outcome ? <span>Outcome: {item.outcome}</span> : null}
                </div>
                {item.notesPreview ? <p className="mt-2 line-clamp-2 text-xs font-bold leading-5 text-slate-500">{item.notesPreview}</p> : null}
              </div>
              <div className="flex w-full flex-col gap-2 xl:w-auto xl:min-w-[240px]">
                <Button type="button" size="sm" variant="secondary" onClick={() => openItem(item)}>{item.actionLabel}</Button>
                {canManage && item.type !== "leadSource" ? (
                  <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-1">
                    <Button type="button" size="sm" onClick={() => setDraftItemId(item.id)} disabled={disabled}>Draft / Copy</Button>
                    <Button type="button" size="sm" variant="ghost" onClick={() => runQueueAction(item, "log-call")} disabled={disabled}>Log Manual Call</Button>
                    <Button type="button" size="sm" variant="ghost" onClick={() => runQueueAction(item, "log-email")} disabled={disabled}>Log Manual Email</Button>
                    <Button type="button" size="sm" variant="ghost" onClick={() => runQueueAction(item, "log-text")} disabled={disabled}>Log Manual Text</Button>
                    <Button type="button" size="sm" variant="ghost" onClick={() => runQueueAction(item, "waiting")} disabled={disabled}>Mark Waiting</Button>
                    <Button type="button" size="sm" variant="ghost" onClick={() => runQueueAction(item, "follow-up-tomorrow")} disabled={disabled}>Follow-Up Tomorrow</Button>
                    <Button type="button" size="sm" variant="ghost" onClick={() => runQueueAction(item, "follow-up-two-days")} disabled={disabled}>Follow-Up in 2 Days</Button>
                  </div>
                ) : null}
              </div>
            </div>
          </div>
        )) : (
          <StateCard title="Follow-up queue is clear" description="Due, overdue, waiting, not-contacted, and recently contacted records will appear here." tone="slate" />
        )}
      </div>
    </Card>
  );
}

function DailySourceCheckPanel({
  sources = [],
  canManage = false,
  disabled = false,
  onMarkSourceChecked = async () => false,
  onStartLeadFromSource = () => {},
}) {
  const today = todayDateInputValue();
  const checkState = useMemo(() => deriveDailySourceCheckState(sources, { today }), [sources, today]);
  const [checkingSourceId, setCheckingSourceId] = useState("");
  const [checkDraft, setCheckDraft] = useState({ checkedAt: today, nextCheckAt: "", checkNote: "" });
  const [message, setMessage] = useState("");

  function beginCheck(source) {
    const checkedAt = todayDateInputValue();
    setCheckingSourceId(source.id);
    setCheckDraft({
      checkedAt,
      nextCheckAt: calculateNextLeadSourceCheckDate(source.checkCadence, checkedAt),
      checkNote: "",
    });
    setMessage("");
  }

  function cancelCheck() {
    setCheckingSourceId("");
    setCheckDraft({ checkedAt: todayDateInputValue(), nextCheckAt: "", checkNote: "" });
  }

  function updateCheckedAt(value, source) {
    setCheckDraft((current) => ({
      ...current,
      checkedAt: value,
      nextCheckAt: calculateNextLeadSourceCheckDate(source.checkCadence, value),
    }));
  }

  async function submitCheck(event, source) {
    event.preventDefault();
    if (!canManage) return;
    const didSave = await onMarkSourceChecked(source.id, checkDraft);
    if (didSave) {
      setMessage(`${source.name} marked checked.`);
      cancelCheck();
    }
  }

  function startLead(source) {
    onStartLeadFromSource(source);
    setMessage(`Source context copied into the new lead form for ${source.name}.`);
  }

  function SourceActions({ source }) {
    const isChecking = checkingSourceId === source.id;
    return (
      <div className="mt-3">
        <div className="flex flex-col gap-2 sm:flex-row sm:flex-wrap">
          {source.url ? (
            <a className="inline-flex min-w-0 max-w-full items-center justify-center rounded-2xl border border-blue-100 bg-white px-3 py-2 text-center text-xs font-black leading-tight text-slate-700 transition hover:bg-blue-50" href={source.url} target="_blank" rel="noreferrer">Open source URL</a>
          ) : null}
          {canManage ? <Button type="button" size="sm" onClick={() => beginCheck(source)} disabled={disabled}>Mark Checked</Button> : null}
          {canManage ? <Button type="button" size="sm" variant="secondary" onClick={() => startLead(source)} disabled={disabled}>Add Lead From Source</Button> : null}
        </div>
        {isChecking ? (
          <form onSubmit={(event) => submitCheck(event, source)} className="mt-3 rounded-2xl border border-blue-100 bg-blue-50/60 p-3">
            <div className="grid gap-3 md:grid-cols-2">
              <InputField label="Checked date" type="date" value={checkDraft.checkedAt} onChange={(event) => updateCheckedAt(event.target.value, source)} disabled={disabled} />
              <InputField label="Next check date" type="date" value={checkDraft.nextCheckAt} onChange={(event) => setCheckDraft((current) => ({ ...current, nextCheckAt: event.target.value }))} disabled={disabled} />
            </div>
            <TextAreaField label="Check note / result" value={checkDraft.checkNote} onChange={(event) => setCheckDraft((current) => ({ ...current, checkNote: event.target.value }))} disabled={disabled} placeholder="Example: no matching bids found today; check again next week." />
            <p className="mt-2 text-xs font-bold text-slate-500">Manual and as-needed cadences leave the next check blank unless you set one.</p>
            <div className="mt-3 flex flex-col gap-2 sm:flex-row">
              <Button type="submit" size="sm" disabled={disabled}>Save Check</Button>
              <Button type="button" size="sm" variant="secondary" onClick={cancelCheck} disabled={disabled}>Cancel</Button>
            </div>
          </form>
        ) : null}
      </div>
    );
  }

  function SourceCard({ source, tone = "blue", helper }) {
    const scoutBrief = buildOpportunityScoutSourceBrief(source);
    return (
      <div className="rounded-2xl border border-blue-100 bg-white p-4 shadow-sm">
        <div className="flex min-w-0 flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2">
              <p className="break-words text-sm font-black text-slate-950">{source.name || "Unnamed source"}</p>
              <Badge tone={tone}>{helper}</Badge>
            </div>
            <p className="mt-1 break-words text-xs font-bold text-slate-500">{[source.type, leadSourceLocation(source), source.checkCadence || "Manual"].filter(Boolean).join(" / ")}</p>
            <p className="mt-2 text-sm leading-6 text-slate-600">Last checked: {source.lastCheckedAt || "Not set"} / Next check: {source.nextCheckAt || "Not scheduled"}</p>
          </div>
        </div>
        <div className="co-source-check-brief" data-tone={tone}>
          <div className="co-source-check-brief-head">
            <span>Scout brief</span>
            <code>{scoutBrief.query}</code>
            <p>{scoutBrief.headline}</p>
          </div>
          <div className="co-source-check-brief-list">
            {scoutBrief.checkFor.map((item) => <em key={item}>{item}</em>)}
          </div>
          <p className="co-source-check-brief-result">{scoutBrief.resultPrompt}</p>
        </div>
        <SourceActions source={source} />
      </div>
    );
  }

  function SourceSection({ title, description, rows, emptyTitle, tone, helperForSource }) {
    return (
      <div className="min-w-0 space-y-3">
        <SectionHeader title={title} description={description} action={<Badge tone={rows.length > 0 ? tone : "slate"}>{rows.length}</Badge>} />
        {rows.length > 0 ? rows.slice(0, 6).map((source) => (
          <SourceCard key={`${title}-${source.id}`} source={source} tone={tone} helper={helperForSource(source)} />
        )) : <StateCard title={emptyTitle} description="Sources will appear here when their check dates match this bucket." tone="slate" />}
      </div>
    );
  }

  return (
    <Card className="overflow-hidden">
      <div className="border-b border-blue-100 bg-amber-50/70 p-4">
        <div className="flex min-w-0 flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
          <div className="min-w-0">
            <Badge tone="amber">Daily Source Check</Badge>
            <h3 className="mt-2 text-base font-black text-slate-950">Manual source check queue</h3>
            <p className="mt-1 text-sm leading-6 text-slate-600">
              Check bid pages, plan rooms, referrals, and relationship sources manually. Nothing is scraped, emailed, texted, or checked automatically.
            </p>
          </div>
          <div className="grid min-w-0 gap-2 sm:grid-cols-4 xl:min-w-[560px]">
            <div className="rounded-2xl border border-amber-100 bg-white p-3"><p className="text-lg font-black text-slate-950">{checkState.stats.overdue}</p><Badge tone={checkState.stats.overdue > 0 ? "red" : "slate"}>Overdue</Badge></div>
            <div className="rounded-2xl border border-amber-100 bg-white p-3"><p className="text-lg font-black text-slate-950">{checkState.stats.dueToday}</p><Badge tone={checkState.stats.dueToday > 0 ? "amber" : "slate"}>Due today</Badge></div>
            <div className="rounded-2xl border border-amber-100 bg-white p-3"><p className="text-lg font-black text-slate-950">{checkState.stats.upcoming}</p><Badge tone="blue">Upcoming</Badge></div>
            <div className="rounded-2xl border border-amber-100 bg-white p-3"><p className="text-lg font-black text-slate-950">{checkState.stats.recentlyChecked}</p><Badge tone="green">Recently checked</Badge></div>
          </div>
        </div>
        {message ? <p className="mt-3 rounded-2xl border border-blue-100 bg-white px-3 py-2 text-sm font-bold text-blue-800">{message}</p> : null}
      </div>

      <div className="grid gap-5 p-4 xl:grid-cols-2">
        <SourceSection
          title="Overdue Sources"
          description="Active sources with a next check date before today."
          rows={checkState.overdueSources}
          emptyTitle="No overdue sources"
          tone="red"
          helperForSource={(source) => `Overdue ${source.nextCheckAt}`}
        />
        <SourceSection
          title="Sources Due Today"
          description="Active sources scheduled for today."
          rows={checkState.dueTodaySources}
          emptyTitle="No sources due today"
          tone="amber"
          helperForSource={() => "Due today"}
        />
        <SourceSection
          title="Upcoming Sources"
          description="Active sources scheduled after today."
          rows={checkState.upcomingSources}
          emptyTitle="No upcoming checks scheduled"
          tone="blue"
          helperForSource={(source) => `Next ${source.nextCheckAt}`}
        />
        <SourceSection
          title="Recently Checked Sources"
          description="Newest manual source checks, sorted by last checked date."
          rows={checkState.recentlyCheckedSources}
          emptyTitle="No checks recorded yet"
          tone="green"
          helperForSource={(source) => `Checked ${source.lastCheckedAt}`}
        />
      </div>
    </Card>
  );
}

function LeadSourcesPanel({
  sources = [],
  canManage = false,
  onCreateSource = async () => false,
  onUpdateSource = async () => false,
  onArchiveSource = async () => false,
  onRestoreSource = async () => false,
  disabled = false,
}) {
  const [draft, setDraft] = useState(INITIAL_LEAD_SOURCE_FORM);
  const [editingId, setEditingId] = useState("");
  const [showInactive, setShowInactive] = useState(false);
  const [query, setQuery] = useState("");
  const [formError, setFormError] = useState("");
  const sourceState = useMemo(() => deriveLeadSourceListState(sources, { includeInactive: showInactive, query }), [query, showInactive, sources]);
  const activeEditingSource = editingId ? sources.find((source) => source.id === editingId) : null;

  function resetDraft() {
    setDraft(INITIAL_LEAD_SOURCE_FORM);
    setEditingId("");
    setFormError("");
  }

  function setDraftField(field, value) {
    setDraft((current) => ({ ...current, [field]: value }));
  }

  function editSource(source) {
    setEditingId(source.id);
    setDraft(createLeadSourceDraft(source));
    setFormError("");
  }

  function applyStarter(starterId) {
    if (!starterId) return;
    setDraft(createLeadSourceDraftFromStarter(starterId));
    setEditingId("");
    setFormError("");
  }

  async function submitSource(event) {
    event.preventDefault();
    if (!canManage) return;
    const errors = validateLeadSourcePayload(draft, { existing: activeEditingSource });
    if (errors.length > 0) {
      setFormError(errors[0]);
      return;
    }

    const didSave = editingId
      ? await onUpdateSource(editingId, draft)
      : await onCreateSource(draft);

    if (didSave) {
      resetDraft();
    }
  }

  return (
    <Card className="overflow-hidden">
      <div className="border-b border-blue-100 bg-blue-50/60 p-4">
        <div className="flex min-w-0 flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
          <div className="min-w-0">
            <Badge tone="green">Lead Sources</Badge>
            <h3 className="mt-2 text-base font-black text-slate-950">Sources to check manually</h3>
            <p className="mt-1 text-sm leading-6 text-slate-600">
              Track bid pages, plan rooms, referral lists, and relationship sources. This is source management only; no scraping, AI, or automatic checks run here.
            </p>
          </div>
          <div className="grid min-w-0 gap-2 sm:grid-cols-3 xl:min-w-[420px]">
            <div className="rounded-2xl border border-blue-100 bg-white p-3">
              <p className="text-lg font-black text-slate-950">{sourceState.stats.active}</p>
              <Badge tone="green">Active</Badge>
            </div>
            <div className="rounded-2xl border border-blue-100 bg-white p-3">
              <p className="text-lg font-black text-slate-950">{sourceState.stats.inactive}</p>
              <Badge tone="slate">Inactive</Badge>
            </div>
            <div className="rounded-2xl border border-blue-100 bg-white p-3">
              <p className="text-lg font-black text-slate-950">{sourceState.stats.dueForCheck}</p>
              <Badge tone={sourceState.stats.dueForCheck > 0 ? "amber" : "slate"}>Due</Badge>
            </div>
          </div>
        </div>
      </div>

      <div className="grid gap-4 p-4 xl:grid-cols-[minmax(0,1.15fr)_minmax(360px,0.85fr)]">
        <div className="min-w-0 space-y-3">
          <div className="flex min-w-0 flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <input
              className="field-input sm:max-w-md"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Search sources, cities, notes..."
            />
            <label className="flex items-center gap-2 text-xs font-black uppercase tracking-[0.22em] text-slate-500">
              <input type="checkbox" checked={showInactive} onChange={(event) => setShowInactive(event.target.checked)} />
              Show inactive
            </label>
          </div>

          {sourceState.sources.length > 0 ? (
            <div className="space-y-3">
              {sourceState.sources.map((source) => (
                <div key={source.id} className="rounded-2xl border border-blue-100 bg-white p-4 shadow-sm">
                  <div className="flex min-w-0 flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                    <div className="min-w-0">
                      <div className="flex flex-wrap items-center gap-2">
                        <p className="break-words text-sm font-black text-slate-950">{source.name || "Unnamed source"}</p>
                        <Badge tone={source.status === "Active" ? "green" : "slate"}>{source.status || "Active"}</Badge>
                      </div>
                      <p className="mt-1 break-words text-xs font-bold text-slate-500">
                        {[source.type, leadSourceLocation(source), source.tradeFocus].filter(Boolean).join(" / ")}
                      </p>
                      <p className="mt-2 break-words text-sm leading-6 text-slate-600">{source.notes || "No notes yet."}</p>
                      <div className="mt-3 flex flex-wrap gap-2 text-xs font-bold text-slate-500">
                        <span>Cadence: {source.checkCadence || "Manual"}</span>
                        <span>Last: {source.lastCheckedAt || "Not set"}</span>
                        <span>Next: {source.nextCheckAt || "Not set"}</span>
                      </div>
                    </div>
                    <div className="flex w-full flex-col gap-2 sm:w-auto">
                      {source.url ? (
                        <a className="inline-flex min-w-0 max-w-full items-center justify-center rounded-2xl border border-blue-100 bg-white px-3 py-2 text-center text-xs font-black leading-tight text-slate-700 transition hover:bg-blue-50" href={source.url} target="_blank" rel="noreferrer">Open source URL</a>
                      ) : null}
                      {canManage ? <Button type="button" size="sm" variant="secondary" onClick={() => editSource(source)} disabled={disabled}>Edit</Button> : null}
                      {canManage && source.status === "Active" ? (
                        <Button type="button" size="sm" variant="ghost" onClick={() => onArchiveSource(source.id)} disabled={disabled}>Deactivate</Button>
                      ) : null}
                      {canManage && source.status !== "Active" ? (
                        <Button type="button" size="sm" variant="ghost" onClick={() => onRestoreSource(source.id)} disabled={disabled}>Reactivate</Button>
                      ) : null}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <StateCard title="No lead sources yet" description="Add bid pages, plan rooms, referral lists, or other manual sources for the office to review." tone="slate" />
          )}
        </div>

        <form onSubmit={submitSource} className="min-w-0 rounded-3xl border border-blue-100 bg-white p-4 shadow-sm">
          <SectionHeader
            title={editingId ? "Edit lead source" : "Add lead source"}
            description="Name is required. URL is optional because relationship sources may not have one."
          />
          <div className="mt-4 space-y-3">
            <div className="co-lead-source-starter-grid">
              {LEAD_SOURCE_STARTERS.map((starter) => (
                <button
                  key={starter.id}
                  type="button"
                  className="co-lead-source-starter co-focus-ring"
                  onClick={() => applyStarter(starter.id)}
                  disabled={!canManage || disabled}
                >
                  <span>{starter.group || "Starter"}</span>
                  <strong>{starter.label}</strong>
                  <em>{starter.description || starter.source?.notes || "Use this as an editable source starter."}</em>
                </button>
              ))}
            </div>
            <SelectField label="Starter template" value="" onChange={(event) => applyStarter(event.target.value)} disabled={!canManage || disabled}>
              <option value="">Choose starter...</option>
              {LEAD_SOURCE_STARTERS.map((starter) => <option key={starter.id} value={starter.id}>{starter.label}</option>)}
            </SelectField>
            <InputField label="Source name" value={draft.name} onChange={(event) => setDraftField("name", event.target.value)} disabled={!canManage || disabled} required />
            <SelectField label="Type/category" value={draft.type} onChange={(event) => setDraftField("type", event.target.value)} disabled={!canManage || disabled}>
              {LEAD_SOURCE_TYPE_OPTIONS.map((type) => <option key={type} value={type}>{type}</option>)}
            </SelectField>
            <InputField label="URL / website / portal link" value={draft.url} onChange={(event) => setDraftField("url", event.target.value)} disabled={!canManage || disabled} placeholder="https://example.com/bids" />
            <div className="grid gap-3 sm:grid-cols-2">
              <InputField label="City" value={draft.city} onChange={(event) => setDraftField("city", event.target.value)} disabled={!canManage || disabled} />
              <InputField label="State" value={draft.state} onChange={(event) => setDraftField("state", event.target.value)} disabled={!canManage || disabled} />
            </div>
            <InputField label="Service area" value={draft.serviceArea} onChange={(event) => setDraftField("serviceArea", event.target.value)} disabled={!canManage || disabled} />
            <InputField label="Trade / industry focus" value={draft.tradeFocus} onChange={(event) => setDraftField("tradeFocus", event.target.value)} disabled={!canManage || disabled} />
            <SelectField label="Check cadence" value={draft.checkCadence} onChange={(event) => setDraftField("checkCadence", event.target.value)} disabled={!canManage || disabled}>
              {LEAD_SOURCE_CADENCE_OPTIONS.map((cadence) => <option key={cadence} value={cadence}>{cadence}</option>)}
            </SelectField>
            <div className="grid gap-3 sm:grid-cols-2">
              <InputField label="Last checked" type="date" value={draft.lastCheckedAt} onChange={(event) => setDraftField("lastCheckedAt", event.target.value)} disabled={!canManage || disabled} />
              <InputField label="Next check" type="date" value={draft.nextCheckAt} onChange={(event) => setDraftField("nextCheckAt", event.target.value)} disabled={!canManage || disabled} />
            </div>
            <SelectField label="Status" value={draft.status} onChange={(event) => setDraftField("status", event.target.value)} disabled={!canManage || disabled}>
              <option>Active</option>
              <option>Inactive</option>
            </SelectField>
            <TextAreaField label="Notes" value={draft.notes} onChange={(event) => setDraftField("notes", event.target.value)} disabled={!canManage || disabled} placeholder="Do not store passwords, API keys, or private credentials here." />
            {formError ? <p className="rounded-2xl border border-red-100 bg-red-50 p-3 text-sm font-bold text-red-700">{formError}</p> : null}
            <div className="flex flex-col gap-2 sm:flex-row">
              <Button type="submit" disabled={!canManage || disabled}>{editingId ? "Save Source" : "Add Source"}</Button>
              {editingId ? <Button type="button" variant="secondary" onClick={resetDraft} disabled={disabled}>Cancel</Button> : null}
            </div>
          </div>
        </form>
      </div>
    </Card>
  );
}

function LeadCommandRail({
  lead,
  onFieldChange,
  onCreateJob,
  onCreateEstimateFromLead = () => {},
  onScoreLead = () => {},
  onCheckMissingInfo = () => {},
  onGenerateLeadAssistant = () => {},
  onConvertToCustomer = () => {},
  onArchive,
  onRestore,
  onDelete,
  users = [],
  customers = [],
  contactHistory = [],
  contactHistoryPermissions,
  onCreateContactHistory,
  onUpdateContactHistory,
  onArchiveContactHistory,
  onRestoreContactHistory,
  disabled,
  saveState,
  canManage = true,
  canCreateEstimate = false,
  leadAssistantState = null,
}) {
  if (!lead) {
    return (
      <div className="co-leads-right-rail space-y-4">
        <Card className="co-leads-rail-card p-4">
          <SectionHeader title="Selected lead summary" description="Choose a lead from the inbox to review actions, missing info, and next steps." />
          <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5 text-center text-sm font-bold text-slate-500">No lead selected.</div>
        </Card>
      </div>
    );
  }

  const phone = leadContactPhone(lead);
  const email = leadContactEmail(lead);
  const missingItems = Array.isArray(lead.missingInfoItems) ? lead.missingInfoItems : [];
  const assistant = leadAssistantState?.leadId === lead.id ? leadAssistantState : null;
  const readinessRows = [
    { label: "Contact info confirmed", ok: Boolean(phone || email) },
    { label: "Job address confirmed", ok: Boolean(lead.city || lead.address || lead.projectAddress) },
    { label: "Scope description noted", ok: Boolean(lead.project || lead.scopeSummary || lead.notes) },
    { label: "Next step assigned", ok: Boolean(lead.nextStep) },
    { label: "Follow-up scheduled", ok: Boolean(lead.followUpDueAt) },
  ];
  const recentHistory = contactHistoryTimeline(contactHistory, "lead", lead.id).slice(0, 5);

  return (
    <div className="co-leads-right-rail space-y-4">
      <Card className="co-leads-rail-card p-4">
        <div className="flex min-w-0 items-start justify-between gap-3">
          <div className="min-w-0">
            <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-500">Selected Lead Summary</p>
            <h3 className="mt-2 break-words text-xl font-black text-slate-950">{lead.customer || "Unnamed lead"}</h3>
            <p className="mt-1 break-words text-xs font-bold text-slate-500">{[lead.project, lead.city, leadSourceLabel(lead.source || "Call-in")].filter(Boolean).join(" / ")}</p>
          </div>
          <StatusBadge status={isLeadFollowUpDue(lead) ? "Follow-Up Due" : lead.status || "New"} />
        </div>
        <div className="mt-4 grid gap-2 text-sm font-bold text-slate-700">
          {phone ? <p><span className="text-slate-400">Phone:</span> {phone}</p> : null}
          {email ? <p><span className="text-slate-400">Email:</span> {email}</p> : null}
          <p><span className="text-slate-400">Owner:</span> {lead.owner || "Unassigned"}</p>
          <p><span className="text-slate-400">Value:</span> {currency(lead.value)}</p>
          <p><span className="text-slate-400">Next follow-up:</span> {formatLeadFollowUpDate(lead.followUpDueAt)}</p>
        </div>
        <div className="mt-4 grid grid-cols-2 gap-2">
          <Button type="button" size="sm" onClick={() => onCreateEstimateFromLead(lead)} disabled={disabled || Boolean(lead.archivedAt) || !canManage || !canCreateEstimate}>Create Estimate</Button>
          <Button type="button" size="sm" variant="secondary" onClick={onCreateJob} disabled={disabled || Boolean(lead.archivedAt) || !canManage}>Create Job</Button>
          <Button type="button" size="sm" variant="secondary" onClick={onConvertToCustomer} disabled={disabled || Boolean(lead.archivedAt) || !canManage}>Convert</Button>
          {lead.archivedAt ? (
            <Button type="button" size="sm" variant="secondary" onClick={onRestore} disabled={disabled || !canManage}>Restore</Button>
          ) : (
            <Button type="button" size="sm" variant="secondary" onClick={onArchive} disabled={disabled || !canManage}>Archive</Button>
          )}
        </div>
        {lead.archivedAt ? <Button type="button" size="sm" variant="danger" className="mt-2 w-full" onClick={onDelete} disabled={disabled || !canManage}>Delete Permanently</Button> : null}
        <SaveStateText saveState={saveState} />
      </Card>

      <Card className="co-leads-rail-card p-4">
        <SectionHeader title="Missing info / readiness" description="Keep the lead ready for estimating and follow-up." action={<LeadMissingInfoBadge lead={lead} />} />
        <div className="space-y-2">
          {readinessRows.map((row) => (
            <div key={row.label} className="flex items-center justify-between gap-3 rounded-xl border border-slate-200 bg-white px-3 py-2">
              <span className="text-sm font-bold text-slate-700">{row.label}</span>
              <Badge tone={row.ok ? "green" : "amber"}>{row.ok ? "OK" : "Needs"}</Badge>
            </div>
          ))}
        </div>
        {missingItems.length > 0 ? (
          <div className="mt-3 rounded-xl border border-amber-100 bg-amber-50/70 p-3">
            <p className="text-[11px] font-black uppercase tracking-[0.16em] text-amber-700">Missing items</p>
            <ul className="mt-2 space-y-1 text-sm font-bold leading-5 text-slate-700">
              {missingItems.slice(0, 4).map((item) => <li key={item.key || item.label}>- {item.label || item.reason}</li>)}
            </ul>
          </div>
        ) : null}
        <div className="mt-3 grid grid-cols-2 gap-2">
          <Button type="button" size="sm" variant="secondary" onClick={() => onCheckMissingInfo(lead)} disabled={disabled || Boolean(lead.archivedAt) || !canManage}>{leadHasMissingInfoCheck(lead) ? "Re-check" : "Check Info"}</Button>
          <Button type="button" size="sm" variant="secondary" onClick={() => onScoreLead(lead)} disabled={disabled || Boolean(lead.archivedAt) || !canManage}>{leadHasScore(lead) ? "Re-score" : "Score"}</Button>
        </div>
      </Card>

      <details className="co-leads-rail-details">
        <summary>
          <span>Lead edit</span>
          <span>Status, owner, follow-up, and notes</span>
        </summary>
        <div className="grid gap-3 p-3">
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-1">
            <SelectField label="Status" value={lead.status || "New"} onChange={(event) => onFieldChange("status", event.target.value)} disabled={!canManage || disabled}>
              <option>New</option>
              <option>Contacted</option>
              <option>Site Visit</option>
              <option>Estimate Sent</option>
              <option>Approved</option>
            </SelectField>
            <SelectField label="Priority" value={lead.priority || "Normal"} onChange={(event) => onFieldChange("priority", event.target.value)} disabled={!canManage || disabled}>
              <option>Low</option>
              <option>Normal</option>
              <option>High</option>
            </SelectField>
          </div>
          <SelectField label="Owner" value={lead.ownerId || ""} onChange={(event) => onFieldChange("ownerId", event.target.value)} disabled={!canManage || disabled}>
            <option value="">Unassigned</option>
            {users.map((user) => <option key={user.id} value={user.id}>{user.name}</option>)}
          </SelectField>
          <InputField label="Follow-up due" type="date" value={lead.followUpDueAt || ""} onChange={(event) => onFieldChange("followUpDueAt", event.target.value)} disabled={!canManage || disabled} />
          <InputField label="Next step" value={lead.nextStep || ""} onChange={(event) => onFieldChange("nextStep", event.target.value)} disabled={!canManage || disabled} />
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-1">
            <InputField label="City" value={lead.city || ""} onChange={(event) => onFieldChange("city", event.target.value)} disabled={!canManage || disabled} />
            <InputField label="Value" type="number" value={lead.value || ""} onChange={(event) => onFieldChange("value", Number(event.target.value))} disabled={!canManage || disabled} />
          </div>
          <SelectField label="Linked customer" value={lead.customerId || ""} onChange={(event) => onFieldChange("customerId", event.target.value)} disabled={!canManage || disabled}>
            <option value="">Create or match automatically</option>
            {customers.filter((customer) => !customer.archivedAt).map((customer) => <option key={customer.id} value={customer.id}>{customer.name}</option>)}
          </SelectField>
          <TextAreaField label="Notes" value={lead.notes || ""} onChange={(event) => onFieldChange("notes", event.target.value)} disabled={!canManage || disabled} className="field-input min-h-24 resize-y" />
        </div>
      </details>

      <Card className="co-leads-rail-card p-4">
        <SectionHeader title="AI lead assistant" description="Draft-only support for next steps and outreach copy." action={<Badge tone="blue">Beta</Badge>} />
        <Button type="button" className="w-full" onClick={() => onGenerateLeadAssistant(lead)} disabled={disabled || Boolean(lead.archivedAt) || !canManage || Boolean(assistant?.loading)}>
          {assistant?.loading ? "Generating..." : assistant?.result?.ok ? "Regenerate Drafts" : "Generate Drafts"}
        </Button>
        {assistant?.error ? <p className="mt-3 rounded-xl border border-amber-100 bg-amber-50 px-3 py-2 text-sm font-bold text-amber-800">{assistant.error}</p> : null}
        {assistant?.result?.ok ? (
          <div className="mt-3 space-y-3 text-sm font-bold leading-5 text-slate-700">
            <p><span className="text-slate-400">Summary:</span> {assistant.result.leadSummary || "Review the lead before follow-up."}</p>
            <p><span className="text-slate-400">Next step:</span> {assistant.result.recommendedNextStep || "Choose the next office action."}</p>
          </div>
        ) : null}
      </Card>

      <Card className="co-leads-rail-card p-4">
        <SectionHeader title="Recent contact history" description="Latest outreach tied to this lead." action={<Badge tone="slate">{recentHistory.length}</Badge>} />
        {recentHistory.length > 0 ? (
          <div className="space-y-2">
            {recentHistory.map((item) => (
              <div key={item.id} className="rounded-xl border border-slate-200 bg-white p-3">
                <p className="text-sm font-black text-slate-950">{item.title || item.method || "Contact logged"}</p>
                <p className="mt-1 text-xs font-bold leading-5 text-slate-500">{item.description || item.notes || formatDateTime(item.createdAt)}</p>
              </div>
            ))}
          </div>
        ) : (
          <p className="rounded-xl border border-dashed border-slate-300 bg-slate-50 p-3 text-sm font-bold text-slate-500">No contact history yet.</p>
        )}
        <details className="co-leads-rail-details co-leads-contact-editor mt-3">
          <summary>
            <span>Log contact / edit history</span>
            <span>Manual outreach notes</span>
          </summary>
          <div className="pt-3">
            <ContactHistoryPanel
              entityType="lead"
              entity={lead}
              records={contactHistory}
              permissions={contactHistoryPermissions}
              disabled={disabled}
              onCreate={onCreateContactHistory}
              onUpdate={onUpdateContactHistory}
              onArchive={onArchiveContactHistory}
              onRestore={onRestoreContactHistory}
            />
          </div>
        </details>
      </Card>
    </div>
  );
}

function LeadsPage({
  user,
  companyName,
  leads = [],
  leadSources = [],
  contactHistory = [],
  estimates = [],
  rows,
  filter,
  setFilter,
  search,
  setSearch,
  ownerFilter,
  setOwnerFilter,
  sourceFilter,
  setSourceFilter,
  dueFilter,
  setDueFilter,
  scoreFilter,
  setScoreFilter,
  scoreSort,
  setScoreSort,
  users,
  customers,
  permissions,
  selectedLeadId,
  onSelectLead,
  onSelectCustomer,
  selectedLead,
  onLeadFieldChange,
  onScoreLead,
  onCheckMissingInfo,
  onGenerateLeadAssistant,
  leadAssistantState,
  leadDraft,
  setLeadDraft,
  onCreateLead,
  onCreateJobFromLead,
  onCreateEstimateFromLead,
  onConvertLeadToCustomer,
  onArchiveLead,
  onRestoreLead,
  onDeleteLead,
  onCreateLeadSource,
  onUpdateLeadSource,
  onArchiveLeadSource,
  onRestoreLeadSource,
  onMarkLeadSourceChecked,
  onCreateContactHistory,
  onUpdateContactHistory,
  onArchiveContactHistory,
  onRestoreContactHistory,
  onOpenEstimate = () => {},
  relatedLeadRecords,
  setActive,
  busy,
  leadSaveState,
}) {
  const leadInboxState = useMemo(() => deriveLeadInboxState(leads), [leads]);
  const today = todayDateInputValue();
  const [activeLeadTool, setActiveLeadTool] = useState("intake");
  const [showAllMobileLeads, setShowAllMobileLeads] = useState(false);
  const visibleLeadRowCap = 6;
  const mobileLeadPreviewCap = 3;
  const mobileVisibleLeadRowCap = showAllMobileLeads ? visibleLeadRowCap : mobileLeadPreviewCap;
  const canManageSources = permissions?.leads?.canManageSources ?? permissions?.leads?.canManage;
  const leadKpis = [
    { label: "New Leads", value: rows.filter((lead) => lead.status === "New").length, helper: "Uncontacted new leads", icon: "users", tone: "blue", actionLabel: "View new leads", onAction: () => setFilter("New") },
    { label: "Follow-Ups Due", value: rows.filter((lead) => isLeadFollowUpDue(lead, today)).length, helper: "Need your follow-up today", icon: "clipboard", tone: "orange", actionLabel: "View follow-up queue", onAction: () => setDueFilter("Due today") },
    { label: "Overdue", value: rows.filter((lead) => lead.followUpDueAt && String(lead.followUpDueAt).slice(0, 10) < today).length, helper: "Past due follow-ups", icon: "alert", tone: "red", actionLabel: "View overdue", onAction: () => setDueFilter("Overdue") },
    { label: "Waiting on Response", value: rows.filter(isLeadWaitingOnResponse).length, helper: "Customer has not replied", icon: "clock", tone: "amber", actionLabel: "View waiting", onAction: () => setFilter("All") },
    { label: "Ready for Estimate", value: rows.filter(isLeadReadyForEstimate).length, helper: "Ready to build estimate", icon: "check", tone: "green", actionLabel: "View ready leads", onAction: () => setScoreFilter("All scores") },
  ];
  const leadToolTabs = [
    { id: "intake", label: "Intake", count: permissions.leads.canManage ? 1 : 0 },
    { id: "review", label: "Review Queue", count: leadInboxState.items.length },
    { id: "sourceChecks", label: "Source Checks", count: leadSources.length },
    { id: "sources", label: "Lead Sources", count: leadSources.length },
  ];

  function handleStartLeadFromSource(source) {
    const sourceContext = [
      `Lead source: ${source.name || "Unnamed source"}`,
      source.type ? `Type: ${source.type}` : "",
      source.url ? `URL: ${source.url}` : "",
      source.serviceArea ? `Service area: ${source.serviceArea}` : "",
      source.tradeFocus ? `Trade focus: ${source.tradeFocus}` : "",
      source.notes ? `Source notes: ${source.notes}` : "",
    ].filter(Boolean).join("\n");

    setLeadDraft((current) => ({
      ...current,
      customer: "",
      customerId: "",
      city: source.city || source.serviceArea || current.city || "",
      project: source.tradeFocus || "",
      status: "New",
      source: "Lead Finder",
      nextStep: "Review lead found from source",
      notes: sourceContext,
    }));
  }

  function jumpToLeadSection(sectionId) {
    if (typeof document === "undefined") return;
    requestAnimationFrame(() => {
      const target = document.getElementById(sectionId);
      target?.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  }

  function openLeadTools(toolId = "intake") {
    setActiveLeadTool(toolId);
    if (typeof document === "undefined") return;
    requestAnimationFrame(() => {
      const target = document.getElementById("lead-tools-drawer");
      if (target?.tagName === "DETAILS") {
        target.open = true;
      }
      target?.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  }

  return (
    <div className="co-office-page co-leads-page">
      <PageHeader
        eyebrow={companyName || "Office Sales"}
        title="Leads"
        description="Track new leads, follow-ups, estimates, missing info, and next actions from one contractor command view."
        actions={
          <div className="flex flex-wrap gap-2">
            <Button type="button" variant="secondary" onClick={() => { setDueFilter("Due today"); jumpToLeadSection("lead-followup-board"); }}>Open Follow-Up Queue</Button>
            {permissions?.leads?.canManage ? <Button type="button" onClick={() => openLeadTools("intake")}>New Lead</Button> : null}
          </div>
        }
      />
      <div className="co-leads-kpi-grid mx-auto grid w-full max-w-[1520px] min-w-0 grid-cols-1 gap-3 px-5 pb-3 sm:px-6 md:grid-cols-5 lg:px-6">
        {leadKpis.map((item) => <CommandCenterKpiCard key={item.label} item={item} />)}
      </div>

      <div className="co-leads-command-layout mx-auto grid w-full max-w-[1520px] min-w-0 gap-3 px-5 pb-4 sm:px-6 lg:grid-cols-[minmax(0,1fr)_360px] lg:px-6">
        <div className="co-leads-left-stack min-w-0 space-y-3">
          <Card className="co-leads-main-board overflow-hidden">
            <div className="co-leads-board-header border-b border-slate-200 bg-white p-4">
              <div className="flex min-w-0 flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
                <div className="min-w-0">
                  <h2 className="text-base font-black uppercase tracking-[0.04em] text-slate-950">Lead Inbox / Review Queue</h2>
                  <p className="mt-1 text-sm font-bold leading-5 text-slate-600">Filter active leads, select a record, and work the next action from the right rail.</p>
                </div>
                <div className="flex flex-wrap gap-2">
                  <Button type="button" size="sm" variant="secondary" onClick={() => setFilter("All")}>All leads</Button>
                  <Button type="button" size="sm" variant="secondary" onClick={() => setDueFilter("Due today")}>Due today</Button>
                  {permissions?.estimates?.canManage && selectedLead ? <Button type="button" size="sm" onClick={() => onCreateEstimateFromLead(selectedLead)}>Create Estimate</Button> : null}
                </div>
              </div>
            </div>
            <FilterBar filters={["All", "New", "Contacted", "Site Visit", "Estimate Sent", "Approved", "Archived"]} active={filter} setActive={setFilter} search={search} setSearch={setSearch} placeholder="Search name, phone, email, or notes..." />
            <details className="co-leads-advanced-filters border-b border-slate-200 bg-white">
              <summary>
                <span>Advanced filters</span>
                <span>{[ownerFilter !== "All owners" ? ownerFilter : "", sourceFilter !== "All sources" ? sourceFilter : "", dueFilter !== "All due dates" ? dueFilter : "", scoreFilter !== "All scores" ? scoreFilter : ""].filter(Boolean).length || "Owner, source, due date, score"}</span>
              </summary>
              <div className="co-office-filter-grid co-leads-filter-grid grid gap-3 p-3 md:grid-cols-5">
                <SelectField label="Owner" value={ownerFilter} onChange={(event) => setOwnerFilter(event.target.value)}>
                  <option>All owners</option>
                  {Array.from(new Set(users.map((user) => user.name))).sort().map((name) => <option key={name}>{name}</option>)}
                </SelectField>
                <SelectField label="Lead source" value={sourceFilter} onChange={(event) => setSourceFilter(event.target.value)}>
                  <option>All sources</option>
                  {LEAD_SOURCE_OPTIONS.map((source) => <option key={source} value={source}>{source === "public_request_form" ? "Public request form" : source}</option>)}
                </SelectField>
                <SelectField label="Follow-up due" value={dueFilter} onChange={(event) => setDueFilter(event.target.value)}>
                  <option>All due dates</option>
                  <option>Overdue</option>
                  <option>Due today</option>
                  <option>Due soon</option>
                  <option>No due date</option>
                </SelectField>
                <SelectField label="Fit score" value={scoreFilter} onChange={(event) => setScoreFilter(event.target.value)}>
                  <option>All scores</option>
                  {LEAD_SCORE_LABELS.map((label) => <option key={label}>{label}</option>)}
                </SelectField>
                <SelectField label="Sort" value={scoreSort} onChange={(event) => setScoreSort(event.target.value)}>
                  <option>Default order</option>
                  <option>High score first</option>
                </SelectField>
              </div>
            </details>
            <LeadsTable rows={rows} selectedId={selectedLeadId} onSelect={onSelectLead} maxRows={visibleLeadRowCap} mobileMaxRows={mobileVisibleLeadRowCap} />
            <div className="flex min-w-0 flex-wrap items-center justify-between gap-3 border-t border-slate-200 bg-white px-4 py-3">
              <p className="text-sm font-bold text-slate-600">
                <span className="hidden md:inline">Showing {Math.min(rows.length, visibleLeadRowCap)} of {leads.filter((lead) => !lead.archivedAt).length} leads</span>
                <span className="md:hidden">Showing {Math.min(rows.length, mobileVisibleLeadRowCap)} of {leads.filter((lead) => !lead.archivedAt).length} leads</span>
              </p>
              <div className="flex gap-2">
                {rows.length > mobileLeadPreviewCap ? (
                  <Button type="button" size="sm" variant="secondary" className="md:hidden" onClick={() => setShowAllMobileLeads((current) => !current)}>
                    {showAllMobileLeads ? "Show less" : "Show more"}
                  </Button>
                ) : null}
                <Button type="button" size="sm" variant="secondary" onClick={() => setFilter("All")}>Clear filters</Button>
              </div>
            </div>
          </Card>

          <section id="lead-followup-board">
            <FollowUpQueuePanel
              leads={leads}
              customers={customers}
              estimates={estimates}
              leadSources={leadSources}
              contactHistory={contactHistory}
              permissions={permissions}
              companyName={companyName}
              user={user}
              disabled={busy}
              onOpenLead={onSelectLead}
              onOpenCustomer={onSelectCustomer}
              onOpenEstimate={onOpenEstimate}
              onOpenLeads={() => setActive?.("leads")}
              onCreateContactHistory={onCreateContactHistory}
              compact
              maxItems={5}
            />
          </section>
        </div>

        <LeadCommandRail
          lead={selectedLead}
          onFieldChange={onLeadFieldChange}
          onScoreLead={onScoreLead}
          onCheckMissingInfo={onCheckMissingInfo}
          onGenerateLeadAssistant={onGenerateLeadAssistant}
          leadAssistantState={leadAssistantState}
          onCreateJob={onCreateJobFromLead}
          onCreateEstimateFromLead={onCreateEstimateFromLead}
          onConvertToCustomer={onConvertLeadToCustomer}
          onArchive={onArchiveLead}
          onRestore={onRestoreLead}
          onDelete={onDeleteLead}
          users={users}
          customers={customers}
          contactHistory={contactHistory}
          contactHistoryPermissions={permissions.contactHistory}
          onCreateContactHistory={onCreateContactHistory}
          onUpdateContactHistory={onUpdateContactHistory}
          onArchiveContactHistory={onArchiveContactHistory}
          onRestoreContactHistory={onRestoreContactHistory}
          disabled={busy}
          saveState={leadSaveState}
          canManage={permissions.leads.canManage}
          canCreateEstimate={permissions?.estimates?.canManage}
        />
      </div>

      <details id="lead-tools-drawer" className="co-leads-tools-drawer mx-auto w-full max-w-[1520px] min-w-0 px-5 pb-4 sm:px-6 lg:px-8">
        <summary>
          <span>
            <strong>Lead Tools</strong>
            <em>Intake, review queue, source checks, and source management stay available here.</em>
          </span>
          <span>Open tools</span>
        </summary>
        <div className="co-leads-tool-tabs mt-3 flex min-w-0 gap-2 overflow-x-auto pb-1">
          {leadToolTabs.map((tab) => (
            <button key={tab.id} type="button" className={activeLeadTool === tab.id ? "is-active" : ""} onClick={() => setActiveLeadTool(tab.id)}>
              {tab.label}
              <span>{tab.count}</span>
            </button>
          ))}
        </div>
        <div className="co-leads-tools-panel mt-3">
          {activeLeadTool === "intake" ? (
            <LeadIntakeCard draft={leadDraft} setDraft={setLeadDraft} onCreateLead={onCreateLead} disabled={busy} canManage={permissions.leads.canManage} customers={customers} users={users} />
          ) : null}
          {activeLeadTool === "review" ? (
            <LeadInboxReviewQueue inboxState={leadInboxState} onSelectLead={onSelectLead} onScoreLead={onScoreLead} onCheckMissingInfo={onCheckMissingInfo} onCreateEstimateFromLead={onCreateEstimateFromLead} canManage={permissions?.leads?.canManage} canCreateEstimate={permissions?.estimates?.canManage} disabled={busy} />
          ) : null}
          {activeLeadTool === "sourceChecks" ? (
            <DailySourceCheckPanel
              sources={leadSources}
              canManage={canManageSources}
              onMarkSourceChecked={onMarkLeadSourceChecked}
              onStartLeadFromSource={handleStartLeadFromSource}
              disabled={busy}
            />
          ) : null}
          {activeLeadTool === "sources" ? (
            <LeadSourcesPanel
              sources={leadSources}
              canManage={canManageSources}
              onCreateSource={onCreateLeadSource}
              onUpdateSource={onUpdateLeadSource}
              onArchiveSource={onArchiveLeadSource}
              onRestoreSource={onRestoreLeadSource}
              disabled={busy}
            />
          ) : null}
        </div>
      </details>
    </div>
  );
}

function jobDisplayForeman(job) {
  return job?.foremanAssignment?.userName || job?.assignedForemanName || job?.assignedForemanId || "Unassigned";
}

function jobCrewCount(job) {
  const crewAssignments = Array.isArray(job?.crewAssignments) ? job.crewAssignments.length : 0;
  return crewAssignments || Number(job?.crewSizeNeeded || 0) || 0;
}

function jobMissingCrew(job) {
  return !(job?.foremanAssignment?.userId || job?.assignedForemanId || job?.assignedUserId);
}

function jobMissingStart(job) {
  return !job?.scheduledStart;
}

function jobBoardScheduleLabel(job) {
  if (!job?.scheduledStart) return "Unscheduled";
  const parsed = new Date(job.scheduledStart);
  if (Number.isNaN(parsed.getTime())) return job.scheduledStart;
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(parsed);
}

function jobStartupNeedsReview(job) {
  const startupStatus = job?.startupStatus || "Not Started";
  return ["Not Started", "In Progress", "Needs Review"].includes(startupStatus);
}

function JobsTablePolished({ rows, selectedId, onSelect, maxRows = 8, mobileMaxRows = null }) {
  const visibleRows = rows.slice(0, maxRows);
  const mobileRows = rows.slice(0, mobileMaxRows || maxRows);

  return (
    <>
      <div className="co-jobs-mobile-list grid gap-3 p-3 md:hidden">
        {mobileRows.map((job) => {
          const selected = job.id === selectedId;
          const progressValue = Math.max(0, Math.min(100, Number(job.progress || 0)));
          const missingCrew = jobMissingCrew(job);
          const missingStart = jobMissingStart(job);
          const startupNeedsReview = jobStartupNeedsReview(job);
          return (
            <button
              key={job.id}
              type="button"
              onClick={() => onSelect(job.id)}
              className={`co-jobs-mobile-card co-mobile-record-card co-office-list-card w-full rounded-[1.15rem] border p-4 text-left transition ${selected ? "is-selected border-orange-200 bg-orange-50/70" : "border-slate-200 bg-white hover:border-orange-200 hover:bg-orange-50/30"}`}
            >
              <div className="flex min-w-0 items-start justify-between gap-3">
                <div className="min-w-0">
                  <p className="break-words text-base font-black text-slate-950">{jobTitle(job)}</p>
                  <p className="mt-1 break-words text-xs font-bold text-slate-500">{job.id} / {job.customer || "Customer pending"}</p>
                </div>
                <div className="flex shrink-0 flex-col items-end gap-1">
                  <StatusBadge status={jobStatusLabel(job.status || job.stage)} />
                  <StartupStatusBadge status={job.startupStatus || "Not Started"} />
                </div>
              </div>
              <div className="mt-4 grid gap-3 sm:grid-cols-2">
                <div className="min-w-0">
                  <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">Scheduled</p>
                  <p className="mt-1 break-words text-sm font-black text-slate-800">{jobBoardScheduleLabel(job)}</p>
                </div>
                <div className="min-w-0">
                  <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">Foreman</p>
                  <p className="mt-1 break-words text-sm font-bold text-slate-700">{jobDisplayForeman(job)}</p>
                </div>
                <div className="min-w-0">
                  <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">Crew</p>
                  <p className="mt-1 break-words text-sm font-bold text-slate-700">{jobCrewCount(job)} assigned/needed</p>
                </div>
                <div className="min-w-0">
                  <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-400">Next step</p>
                  <p className="mt-1 break-words text-sm font-bold text-slate-700">{jobNextStep(job)}</p>
                </div>
              </div>
              <div className="co-jobs-mobile-readiness">
                <span data-state={missingCrew ? "needs" : "ready"}>Crew <strong>{missingCrew ? "Needs" : "OK"}</strong></span>
                <span data-state={missingStart ? "needs" : "ready"}>Start <strong>{missingStart ? "Needs" : "OK"}</strong></span>
                <span data-state={startupNeedsReview ? "needs" : "ready"}>Startup <strong>{startupNeedsReview ? "Review" : "OK"}</strong></span>
              </div>
              <div className="mt-4 flex min-w-0 items-center gap-3">
                <div className="h-2 min-w-0 flex-1 overflow-hidden rounded-full bg-slate-100">
                  <div className="h-full rounded-full bg-orange-600" style={{ width: `${progressValue}%` }} />
                </div>
                <span className="shrink-0 text-xs font-black text-slate-500">{progressValue}%</span>
                {selected ? <Badge tone="blue">Selected</Badge> : null}
              </div>
            </button>
          );
        })}
      </div>
      <div className="hidden md:block">
        <div className="table-shell">
          <table className="co-jobs-command-table w-full min-w-[780px] text-left">
            <thead>
              <tr>
                <th>Job / Customer</th>
                <th>Status</th>
                <th>Schedule</th>
                <th>Startup</th>
                <th>Foreman / Crew</th>
                <th>Next Step</th>
                <th>Progress</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {visibleRows.map((job) => {
                const selected = job.id === selectedId;
                const progressValue = Math.max(0, Math.min(100, Number(job.progress || 0)));
                return (
                  <tr key={job.id} onClick={() => onSelect(job.id)} className={`cursor-pointer transition hover:bg-orange-50/45 ${selected ? "bg-orange-50/70" : ""}`}>
                    <td>
                      <p className="font-black text-slate-950">{jobTitle(job)}</p>
                      <p className="text-xs font-bold text-slate-500">{job.id} / {job.customer || "Customer pending"}</p>
                    </td>
                    <td><StatusBadge status={jobStatusLabel(job.status || job.stage)} /></td>
                    <td className="font-bold text-slate-700">{jobBoardScheduleLabel(job)}</td>
                    <td><StartupStatusBadge status={job.startupStatus || "Not Started"} /></td>
                    <td className="co-jobs-crew-cell">
                      <p className="font-bold text-slate-700">{jobDisplayForeman(job)}</p>
                      <p className="text-xs font-bold text-slate-500">{jobCrewCount(job)} assigned/needed</p>
                    </td>
                    <td className="font-bold text-slate-700">{jobNextStep(job)}</td>
                    <td>
                      <div className="flex items-center gap-2">
                        <div className="h-2 w-20 overflow-hidden rounded-full bg-slate-100">
                          <div className="h-full rounded-full bg-orange-600" style={{ width: `${progressValue}%` }} />
                        </div>
                        <span className="text-xs font-black text-slate-500">{progressValue}%</span>
                      </div>
                    </td>
                    <td>
                      <div className="flex justify-end gap-1">
                        <button type="button" className="co-jobs-icon-button" onClick={(event) => { event.stopPropagation(); onSelect(job.id); }} aria-label={`Review ${jobTitle(job)}`}>
                          <Icon name="briefcase" />
                        </button>
                        <button type="button" className="co-jobs-icon-button" onClick={(event) => { event.stopPropagation(); onSelect(job.id); }} aria-label={`Open ${jobTitle(job)}`}>
                          <Icon name="arrowUpRight" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </>
  );
}

function JobCommandRailPolished({
  job,
  permissions,
  disabled,
  saveState,
  onArchive,
  onRestore,
  onDelete,
  onPrintPacket,
  onOpenTool,
  onOpenModule,
}) {
  if (!job) {
    return (
      <div className="co-jobs-right-rail space-y-4">
        <Card className="co-jobs-rail-card p-4">
          <SectionHeader title="Selected job summary" description="Choose a job from the board to review schedule, startup, crew, and field actions." />
          <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5 text-center text-sm font-bold text-slate-500">No job selected.</div>
        </Card>
      </div>
    );
  }

  const canManageAll = Boolean(permissions?.jobs?.canManageAll);
  const canPrint = canManageAll || job.canManageField || permissions?.jobs?.canViewMoney;
  const canArchive = canManageAll;
  const startupWarnings = getStartupCriticalWarnings(normalizeStartupChecklist(job.startupChecklist));
  const progressValue = Math.max(0, Math.min(100, Number(job.progress || 0)));
  const missingCrew = jobMissingCrew(job);
  const missingStart = jobMissingStart(job);
  const startupNeedsReview = jobStartupNeedsReview(job);

  return (
    <div className="co-jobs-right-rail space-y-4">
      <Card className="co-jobs-rail-card p-4">
        <div className="flex min-w-0 items-start justify-between gap-3">
          <div className="min-w-0">
            <p className="text-[11px] font-black uppercase tracking-[0.18em] text-slate-500">Selected Job Summary</p>
            <h3 className="mt-2 break-words text-xl font-black text-slate-950">{jobTitle(job)}</h3>
            <p className="mt-1 break-words text-xs font-bold text-slate-500">{job.id} / {job.customer || "Customer pending"}</p>
          </div>
          <StatusBadge status={jobStatusLabel(job.status || job.stage)} />
        </div>
        <div className="co-jobs-selected-metrics">
          <div>
            <span>Schedule</span>
            <strong>{jobBoardScheduleLabel(job)}</strong>
          </div>
          <div>
            <span>Foreman</span>
            <strong>{jobDisplayForeman(job)}</strong>
          </div>
          <div>
            <span>Crew</span>
            <strong>{jobCrewCount(job)} assigned/needed</strong>
          </div>
          <div>
            <span>Startup blockers</span>
            <strong>{startupWarnings.length}</strong>
          </div>
        </div>
        <div className="co-jobs-progress-panel">
          <div className="flex items-center justify-between gap-3">
            <span>Progress</span>
            <strong>{progressValue}%</strong>
          </div>
          <div><span style={{ width: `${progressValue}%` }} /></div>
          <p>{jobNextStep(job)}</p>
        </div>
        <div className="co-jobs-release-pills">
          <span data-state={missingCrew ? "needs" : "ready"}>Crew <strong>{missingCrew ? "Needs" : "OK"}</strong></span>
          <span data-state={missingStart ? "needs" : "ready"}>Start <strong>{missingStart ? "Needs" : "OK"}</strong></span>
          <span data-state={startupNeedsReview ? "needs" : "ready"}>Startup <strong>{startupNeedsReview ? "Review" : "OK"}</strong></span>
        </div>
        <div className="mt-4 grid grid-cols-2 gap-2">
          <Button type="button" size="sm" onClick={() => onOpenTool("details")}>Edit Job</Button>
          <Button type="button" size="sm" variant="secondary" onClick={() => onOpenTool("startup")}>Startup</Button>
          <Button type="button" size="sm" variant="secondary" onClick={() => onOpenTool("crew")}>Crew</Button>
          <Button type="button" size="sm" variant="secondary" onClick={onPrintPacket} disabled={disabled || !canPrint || typeof onPrintPacket !== "function"}>Print</Button>
        </div>
        <SaveStateText saveState={saveState} />
      </Card>

      <Card className="co-jobs-rail-card p-4">
        <SectionHeader title="Readiness" description="Crew, start date, and startup review stay visible before release to field." />
        <div className="grid gap-2">
          <div className="co-jobs-readiness-row">
            <span>Foreman / crew assigned</span>
            <Badge tone={jobMissingCrew(job) ? "amber" : "green"}>{jobMissingCrew(job) ? "Needs" : "OK"}</Badge>
          </div>
          <div className="co-jobs-readiness-row">
            <span>Start date set</span>
            <Badge tone={jobMissingStart(job) ? "amber" : "green"}>{jobMissingStart(job) ? "Needs" : "OK"}</Badge>
          </div>
          <div className="co-jobs-readiness-row">
            <span>Startup reviewed</span>
            <StartupStatusBadge status={job.startupStatus || "Not Started"} />
          </div>
          <div className="co-jobs-readiness-row">
            <span>Visible to field</span>
            <Badge tone={job.visibleToForeman || job.fieldPlanningVisible ? "green" : "slate"}>{job.visibleToForeman || job.fieldPlanningVisible ? "Yes" : "No"}</Badge>
          </div>
        </div>
      </Card>

      <Card className="co-jobs-rail-card p-4">
        <SectionHeader title="Job actions" description="Jump to the operational records that support the selected job." />
        <div className="grid gap-2">
          <button type="button" className="co-jobs-action-row" onClick={() => onOpenModule?.("reports")}>
            <span>Daily reports</span>
            <Icon name="document" />
          </button>
          <button type="button" className="co-jobs-action-row" onClick={() => onOpenModule?.("uploads")}>
            <span>Uploads / photos</span>
            <Icon name="upload" />
          </button>
          <button type="button" className="co-jobs-action-row" onClick={() => onOpenModule?.("deliveryTickets")}>
            <span>Delivery tickets</span>
            <Icon name="clipboard" />
          </button>
          {job.archivedAt ? (
            <>
              <button type="button" className="co-jobs-action-row" onClick={onRestore} disabled={disabled || !canArchive}>
                <span>Restore job</span>
                <Icon name="refresh" />
              </button>
              <button type="button" className="co-jobs-action-row" onClick={onDelete} disabled={disabled || !canArchive}>
                <span>Delete job</span>
                <Icon name="alert" />
              </button>
            </>
          ) : (
            <button type="button" className="co-jobs-action-row" onClick={onArchive} disabled={disabled || !canArchive}>
              <span>Archive job</span>
              <Icon name="database" />
            </button>
          )}
        </div>
      </Card>
    </div>
  );
}

function JobsPage({
  ...props
}) {
  return <JobsPagePolished {...props} />;
}

function JobsPagePolished({
  rows,
  user,
  filter,
  setFilter,
  search,
  setSearch,
  customerFilter,
  setCustomerFilter,
  foremanFilter,
  setForemanFilter,
  dateFilter,
  setDateFilter,
  startupFilter,
  setStartupFilter,
  users,
  selectedJobId,
  onSelectJob,
  selectedJob,
  onJobFieldChange,
  jobDraft,
  setJobDraft,
  onCreateJob,
  onArchiveJob,
  onRestoreJob,
  onDeleteJob,
  onChangeForeman,
  onAddAssignment,
  onUpdateAssignment,
  onRemoveAssignment,
  onAcknowledgeAssignmentNotice,
  busy,
  jobSaveState,
  permissions,
  setActive,
  timeEntries,
  onClockIn,
  onClockOut,
  onStartBreak,
  onEndBreak,
  onPrintJobPacket,
}) {
  const isFieldWorkspace = !permissions.jobs.canManageAll && !permissions.leads.canView;

  if (isFieldWorkspace && permissions.jobs.canManageField) {
    return (
      <ForemanWorkspacePage
        rows={rows}
        user={user}
        selectedJobId={selectedJobId}
        onSelectJob={onSelectJob}
        selectedJob={selectedJob}
        onJobFieldChange={onJobFieldChange}
        busy={busy}
        permissions={permissions}
        setActive={setActive}
        timeEntries={timeEntries}
        onClockIn={onClockIn}
        onClockOut={onClockOut}
        onStartBreak={onStartBreak}
        onEndBreak={onEndBreak}
        onAcknowledgeAssignmentNotice={onAcknowledgeAssignmentNotice}
      />
    );
  }

  if (isFieldWorkspace) {
    return (
      <EmployeeWorkspacePage
        rows={rows}
        user={user}
        selectedJobId={selectedJobId}
        onSelectJob={onSelectJob}
        selectedJob={selectedJob}
        permissions={permissions}
        setActive={setActive}
        timeEntries={timeEntries}
        onClockIn={onClockIn}
        onClockOut={onClockOut}
        onStartBreak={onStartBreak}
        onEndBreak={onEndBreak}
        onAcknowledgeAssignmentNotice={onAcknowledgeAssignmentNotice}
        busy={busy}
      />
    );
  }

  const [showJobTools, setShowJobTools] = useState(false);
  const [activeJobTool, setActiveJobTool] = useState("create");
  const [showAllMobileJobs, setShowAllMobileJobs] = useState(false);
  const jobToolsRef = useRef(null);
  const roleLabel = permissions.jobs.canManageAll ? "office scheduling" : "scope review";
  const pageTitle = "Jobs";
  const pageEyebrow = permissions.jobs.canManageAll ? "Field Ops" : "Job Scope";
  const jobListState = useMemo(() => deriveJobListState(rows, {
    status: filter,
    query: search,
    customer: customerFilter,
    foremanId: foremanFilter,
    date: dateFilter,
  }, users), [customerFilter, dateFilter, filter, foremanFilter, rows, search, users]);
  const visibleRows = jobListState.filteredJobs.filter((job) => startupFilter === "All startup" || (job.startupStatus || "Not Started") === startupFilter);
  const visibleJobRowCap = 8;
  const mobileJobPreviewCap = 3;
  const mobileVisibleJobRowCap = showAllMobileJobs ? visibleJobRowCap : mobileJobPreviewCap;
  const jobKpis = [
    { label: "Jobs", value: visibleRows.length, helper: "Matching current filters", icon: "briefcase", tone: "blue", actionLabel: "View jobs", onAction: () => setFilter("All") },
    { label: "Startup Review", value: visibleRows.filter(jobStartupNeedsReview).length, helper: "Needs office or field prep", icon: "alert", tone: "orange", actionLabel: "Review startup", onAction: () => setStartupFilter("Needs Review") },
    { label: "Missing Crew", value: visibleRows.filter(jobMissingCrew).length, helper: "No foreman or lead assigned", icon: "users", tone: "amber", actionLabel: "Assign crew", onAction: () => setForemanFilter("All foremen") },
    { label: "Missing Start", value: visibleRows.filter(jobMissingStart).length, helper: "Date not set", icon: "clock", tone: "red", actionLabel: "View unscheduled", onAction: () => setDateFilter("Unscheduled") },
    { label: "In Progress", value: visibleRows.filter((job) => normalizeJobStatus(job.status || job.stage) === "in_progress").length, helper: "Active field work", icon: "clock", tone: "green", actionLabel: "View active", onAction: () => setFilter("In Progress") },
  ];
  const jobToolTabs = [
    { id: "create", label: "Create Job", count: permissions.jobs.canCreate ? 1 : 0 },
    { id: "details", label: "Edit / Details", count: selectedJob ? 1 : 0 },
    { id: "startup", label: "Startup", count: selectedJob ? getStartupCriticalWarnings(normalizeStartupChecklist(selectedJob.startupChecklist)).length : 0 },
    { id: "crew", label: "Crew", count: selectedJob ? jobCrewCount(selectedJob) : 0 },
  ];

  function openJobTool(toolId = "details") {
    setActiveJobTool(toolId);
    setShowJobTools(true);
    window.setTimeout(() => jobToolsRef.current?.scrollIntoView?.({ behavior: "smooth", block: "start" }), 0);
  }

  function jumpToJobSection(sectionId) {
    if (typeof document === "undefined") return;
    requestAnimationFrame(() => {
      document.getElementById(sectionId)?.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  }

  function focusNewJob() {
    openJobTool("create");
  }

  return (
    <div className="co-office-page co-jobs-page">
      <PageHeader
        eyebrow={pageEyebrow}
        title={pageTitle}
        description={`Manage active jobs, startup readiness, crews, schedules, and field visibility from one ${roleLabel} command view.`}
        actions={
          <div className="flex flex-wrap gap-2">
            <Button type="button" variant="secondary" onClick={() => jumpToJobSection("jobs-operations-board")}>{visibleRows.length} visible jobs</Button>
            {permissions.jobs.canCreate ? <Button type="button" onClick={focusNewJob}>Create Job</Button> : null}
          </div>
        }
      />
      <div className="co-jobs-kpi-grid mx-auto grid w-full max-w-[1520px] min-w-0 grid-cols-1 gap-3 px-5 pb-3 sm:px-6 md:grid-cols-5 lg:px-6">
        {jobKpis.map((item) => <CommandCenterKpiCard key={item.label} item={item} />)}
      </div>

      <div className="co-jobs-command-layout mx-auto grid w-full max-w-[1520px] min-w-0 gap-3 px-5 pb-4 sm:px-6 lg:grid-cols-[minmax(0,1fr)_360px] lg:px-6">
        <div className="co-jobs-left-stack min-w-0 space-y-3">
          <Card id="jobs-operations-board" className="co-jobs-main-board overflow-hidden">
            <div className="co-jobs-board-header border-b border-slate-200 bg-white p-4">
              <div className="flex min-w-0 flex-col gap-3 xl:flex-row xl:items-start xl:justify-between">
                <div className="min-w-0">
                  <h2 className="text-base font-black uppercase tracking-[0.04em] text-slate-950">Job Operations Board</h2>
                  <p className="mt-1 text-sm font-bold leading-5 text-slate-600">Filter jobs, select a record, and keep schedule, crew, and startup readiness in the right rail.</p>
                </div>
                <div className="flex flex-wrap gap-2">
                  <Button type="button" size="sm" variant="secondary" onClick={() => setFilter("All")}>All jobs</Button>
                  <Button type="button" size="sm" variant="secondary" onClick={() => setStartupFilter("Needs Review")}>Startup review</Button>
                  {permissions.jobs.canCreate ? <Button type="button" size="sm" onClick={focusNewJob}>Create Job</Button> : null}
                </div>
              </div>
            </div>
            <FilterBar filters={["All", "Draft", "Planned", "Scheduled", "In Progress", "Field Complete", "Completed", "Billing Ready", "Closed", "Archived"]} active={filter} setActive={setFilter} search={search} setSearch={setSearch} placeholder="Search job, customer, address, next step..." />
            <details className="co-jobs-advanced-filters border-b border-slate-200 bg-white">
              <summary>
                <span>Advanced filters</span>
                <span>{[customerFilter !== "All customers" ? customerFilter : "", foremanFilter !== "All foremen" ? foremanFilter : "", dateFilter !== "All dates" ? dateFilter : "", startupFilter !== "All startup" ? startupFilter : ""].filter(Boolean).length || "Customer, foreman, date, startup"}</span>
              </summary>
              <div className="co-office-filter-grid co-jobs-filter-grid grid gap-3 p-3 md:grid-cols-4">
                <SelectField label="Customer" value={customerFilter} onChange={(event) => setCustomerFilter(event.target.value)}>
                  <option>All customers</option>
                  {jobListState.customerOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                </SelectField>
                <SelectField label="Foreman" value={foremanFilter} onChange={(event) => setForemanFilter(event.target.value)}>
                  <option>All foremen</option>
                  {jobListState.foremanOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                </SelectField>
                <SelectField label="Date" value={dateFilter} onChange={(event) => setDateFilter(event.target.value)}>
                  <option>All dates</option>
                  <option>Today</option>
                  <option>This Week</option>
                  <option>Upcoming</option>
                  <option>Overdue</option>
                  <option>Unscheduled</option>
                </SelectField>
                <SelectField label="Startup" value={startupFilter} onChange={(event) => setStartupFilter(event.target.value)}>
                  <option>All startup</option>
                  {JOB_STARTUP_STATUSES.map((status) => <option key={status}>{status}</option>)}
                </SelectField>
              </div>
            </details>
            {visibleRows.length === 0 ? (
              <div className="p-5">
                <StateCard title="No jobs match this view" description="Adjust filters or create a job to bring active work into the operations board." tone="blue" />
              </div>
            ) : (
              <JobsTablePolished rows={visibleRows} selectedId={selectedJobId} onSelect={onSelectJob} maxRows={visibleJobRowCap} mobileMaxRows={mobileVisibleJobRowCap} />
            )}
            <div className="flex min-w-0 flex-wrap items-center justify-between gap-3 border-t border-slate-200 bg-white px-4 py-3">
              <p className="text-sm font-bold text-slate-600">
                <span className="hidden md:inline">Showing {Math.min(visibleRows.length, visibleJobRowCap)} of {visibleRows.length} filtered jobs</span>
                <span className="md:hidden">Showing {Math.min(visibleRows.length, mobileVisibleJobRowCap)} of {visibleRows.length} filtered jobs</span>
              </p>
              <div className="flex flex-wrap gap-2">
                {visibleRows.length > mobileJobPreviewCap ? (
                  <Button type="button" size="sm" variant="secondary" className="md:hidden" onClick={() => setShowAllMobileJobs((current) => !current)}>
                    {showAllMobileJobs ? "Show less" : "Show more"}
                  </Button>
                ) : null}
                <Button type="button" size="sm" variant="secondary" onClick={() => { setFilter("All"); setCustomerFilter("All customers"); setForemanFilter("All foremen"); setDateFilter("All dates"); setStartupFilter("All startup"); setSearch(""); }}>Clear filters</Button>
              </div>
            </div>
          </Card>
        </div>

        <JobCommandRailPolished
          job={selectedJob}
          permissions={permissions}
          disabled={busy}
          saveState={jobSaveState}
          onArchive={onArchiveJob}
          onRestore={onRestoreJob}
          onDelete={onDeleteJob}
          onPrintPacket={selectedJob ? () => onPrintJobPacket?.(selectedJob) : undefined}
          onOpenTool={openJobTool}
          onOpenModule={setActive}
        />
      </div>

      <details
        ref={jobToolsRef}
        className="co-jobs-tools-drawer mx-auto w-full max-w-[1520px] min-w-0 px-5 pb-4 sm:px-6 lg:px-8"
        open={showJobTools}
        onToggle={(event) => setShowJobTools(event.currentTarget.open)}
      >
        <summary>
          <span>
            <strong>Job Tools</strong>
            <em>Create jobs, edit details, finish startup readiness, and assign field crews here.</em>
          </span>
          <span>Open tools</span>
        </summary>
        <div className="co-jobs-tool-tabs mt-3 flex min-w-0 gap-2 overflow-x-auto pb-1">
          {jobToolTabs.map((tab) => (
            <button key={tab.id} type="button" className={activeJobTool === tab.id ? "is-active" : ""} onClick={() => setActiveJobTool(tab.id)}>
              {tab.label}
              <span>{tab.count}</span>
            </button>
          ))}
        </div>
        <div className="co-jobs-tools-panel mt-3">
          {activeJobTool === "create" ? (
            <JobPlannerCard draft={jobDraft} setDraft={setJobDraft} onCreateJob={onCreateJob} disabled={busy || !permissions.jobs.canCreate} users={users} canCreate={permissions.jobs.canCreate} />
          ) : null}

          {activeJobTool === "details" ? (
            <JobDetailPanel
              job={selectedJob}
              users={users}
              onFieldChange={onJobFieldChange}
              onArchive={onArchiveJob}
              onRestore={onRestoreJob}
              onDelete={onDeleteJob}
              onChangeForeman={onChangeForeman}
              onAddAssignment={onAddAssignment}
              onUpdateAssignment={onUpdateAssignment}
              onRemoveAssignment={onRemoveAssignment}
              saveState={jobSaveState}
              disabled={busy}
              permissions={permissions}
              onPrintPacket={selectedJob ? () => onPrintJobPacket?.(selectedJob) : undefined}
            />
          ) : null}

          {activeJobTool === "startup" ? (
            <Card className="p-4">
              <SectionHeader title="Startup Readiness" description="Review blockers before the job is treated as ready for field work." action={selectedJob ? <StartupStatusBadge status={selectedJob.startupStatus || "Not Started"} /> : null} />
              {selectedJob && permissions.jobs.canManageAll ? (
                <JobStartupChecklistCard job={selectedJob} onFieldChange={onJobFieldChange} disabled={busy} />
              ) : (
                <StateCard title="Startup review unavailable" description={selectedJob ? "Startup checklist editing is only available to office scheduling roles." : "Select a job before reviewing startup readiness."} tone="slate" />
              )}
            </Card>
          ) : null}

          {activeJobTool === "crew" ? (
            <Card className="p-4">
              <SectionHeader title="Crew / Foreman" description="Assign the foreman and crew without crowding the main job board." />
              {selectedJob ? (
                <JobCrewSection
                  job={selectedJob}
                  users={users}
                  disabled={busy}
                  canManageAssignments={Boolean(permissions?.jobs?.canManageAssignments)}
                  onChangeForeman={onChangeForeman}
                  onAddAssignment={onAddAssignment}
                  onUpdateAssignment={onUpdateAssignment}
                  onRemoveAssignment={onRemoveAssignment}
                />
              ) : (
                <StateCard title="No job selected" description="Select a job before assigning a foreman or crew." tone="blue" />
              )}
            </Card>
          ) : null}
        </div>
      </details>
    </div>
  );
}

function importedDraftStatusTone(status) {
  if (status === "Job Created" || status === "Ready to Create Job") return "green";
  if (status === "Needs Review") return "amber";
  if (status === "Rejected") return "red";
  return "blue";
}

function customerMatchStatusTone(status) {
  if (status === "Matched" || status === "Confirmed") return "green";
  if (status === "Review Required" || status === "Possible Match") return "amber";
  if (status === "New Customer Needed" || status === "No Match") return "blue";
  return "slate";
}

function importedDraftImportedAt(draft) {
  return draft?.importedAt || draft?.createdAt || draft?.updatedAt;
}

function importedDraftLocation(draft) {
  return [draft?.city, draft?.state].filter(Boolean).join(", ") || "Location needs review";
}

function importedDraftSearchMatch(draft, query) {
  const normalizedQuery = String(query || "").trim().toLowerCase();
  if (!normalizedQuery) return true;
  const haystack = [
    draft.jobName,
    draft.customerName,
    draft.contactName,
    draft.city,
    draft.state,
    draft.serviceType,
    draft.projectType,
    draft.scopeSummary,
    draft.opsReadinessLabel,
    draft.importStatus,
    draft.customerMatchStatus,
    draft.opsJobDraftId,
    draft.sourceHandoffId,
  ].filter(Boolean).join(" ").toLowerCase();
  return haystack.includes(normalizedQuery);
}

function ImportedJobDraftsPage({
  drafts,
  jobs,
  customers,
  selectedDraftId,
  onSelectDraft,
  onBackToDrafts,
  onImportPackage,
  onSaveDraft,
  onCreateJobFromDraft,
  onOpenCreatedJob,
  busy,
  permissions,
}) {
  if (!permissions.jobDraftImports?.canView) {
    return (
      <div className="co-office-page co-imports-page">
        <PageHeader eyebrow="Office" title="Imported Job Drafts" description="Imported draft packages are only available to office roles that can create jobs." />
        <div className="px-5 sm:px-6 lg:px-8">
          <StateCard title="Imported drafts unavailable" description="This role cannot import or create jobs from external draft packages." tone="slate" />
        </div>
      </div>
    );
  }

  const selectedDraft = drafts.find((draft) => draft.id === selectedDraftId) || null;

  if (selectedDraft) {
    return (
      <ImportedJobDraftDetailPage
        draft={selectedDraft}
        jobs={jobs}
        customers={customers}
        onBack={onBackToDrafts}
        onCreateJobFromDraft={onCreateJobFromDraft}
        onOpenCreatedJob={onOpenCreatedJob}
        onSaveDraft={onSaveDraft}
        busy={busy}
      />
    );
  }

  return (
      <ImportedJobDraftListPage
        drafts={drafts}
        onImportPackage={onImportPackage}
        onOpenCreatedJob={onOpenCreatedJob}
        onSelectDraft={onSelectDraft}
        busy={busy}
        permissions={permissions}
      />
    );
  }

